class GridConfig:
    """Mutable grid dimensions. Labels are derived, so changing n_cols /
    n_rows at runtime immediately changes the coordinate namespace."""

    def __init__(self, n_cols: int = DEFAULT_N_COLS, n_rows: int = DEFAULT_N_ROWS):
        self.n_cols = n_cols
        self.n_rows = n_rows

    @property
    def columns(self):
        return ALPHABET[:self.n_cols]

    @property
    def rows(self):
        return list(range(1, self.n_rows + 1))

    def col_index(self, letter: str):
        letter = letter.upper()
        cols = self.columns
        return cols.index(letter) if letter in cols else None

    def row_index(self, num: int):
        return num - 1 if 1 <= num <= self.n_rows else None


CONFIG = GridConfig()


def parse_coordinate(text: str):
    """Parse a coordinate like 'G1' or 'K11' into 0-indexed (col_idx, row_idx).

    Returns None if the text isn't a valid, in-range coordinate.
    """
    text = text.strip().upper()
    if len(text) < 2:
        return None
    col_letter = text[0]
    row_part = text[1:]
    col_idx = CONFIG.col_index(col_letter)
    if col_idx is None:
        return None
    if not row_part.isdigit():
        return None
    row_idx = CONFIG.row_index(int(row_part))
    if row_idx is None:
        return None
    return col_idx, row_idx


def coordinate_name(col_idx: int, row_idx: int) -> str:
    """0-indexed (col_idx, row_idx) -> 'G1' style label."""
    return f"{CONFIG.columns[col_idx]}{CONFIG.rows[row_idx]}"


def cell_label(col_idx, row_idx) -> str:
    """coordinate_name, but safe for a cell that is legitimately off the board.

    A computed cell can land past the rim. CONFIG.columns[-1] would happily
    return the LAST column instead of raising, naming a cell on the far side
    of the board -- a wrong answer is worse here than an honest one.
    """
    if col_idx is None or row_idx is None:
        return "--"
    if 0 <= col_idx < CONFIG.n_cols and 0 <= row_idx < CONFIG.n_rows:
        return coordinate_name(col_idx, row_idx)
    return "off board"


# Micro coordinates (user, 2026-10-17). The board's own cells -- "F8" -- are
# the MACRO coordinates the planner, Vision AI and ERR all work in. Each
# macro cell is split MICRO_PER_CELL x MICRO_PER_CELL again: micro columns
# a-d left to right, micro rows 1-4 top to bottom, written after the macro
# cell -- "F8.b3" is the second micro column and third micro row of F8.
# Gripper AI chooses its grip in micro coordinates on a zoomed look at the
# object; the move itself still goes to the macro cell that micro cell is in.
MICRO_PER_CELL = 4
MICRO_COLS = "abcd"
MICRO_RE = re.compile(r"(?<![A-Za-z0-9])([A-Za-z])\s*(\d{1,2})\s*[.:,/\-]?\s*"
                      r"([a-dA-D])\s*([1-4])(?![0-9])")


def micro_name(col: float, row: float) -> str:
    """Grid point (col, row) -> its micro coordinate, "F8.b3"."""
    c = max(0, min(CONFIG.n_cols - 1, int(math.floor(col))))
    r = max(0, min(CONFIG.n_rows - 1, int(math.floor(row))))
    mc = max(0, min(MICRO_PER_CELL - 1, int(math.floor((col - c) * MICRO_PER_CELL))))
    mr = max(0, min(MICRO_PER_CELL - 1, int(math.floor((row - r) * MICRO_PER_CELL))))
    return f"{coordinate_name(c, r)}.{MICRO_COLS[mc]}{mr + 1}"


def parse_micro(text):
    """A micro coordinate ("F8.b3", "f8 b3", "F8:B3") -> the middle of that
    micro cell as a grid point (col, row); None when there is none."""
    for m in MICRO_RE.finditer(str(text or "")):
        cell = parse_coordinate(f"{m.group(1)}{m.group(2)}")
        if cell is None:
            continue
        mc = MICRO_COLS.index(m.group(3).lower())
        mr = int(m.group(4)) - 1
        return (cell[0] + (mc + 0.5) / MICRO_PER_CELL,
                cell[1] + (mr + 0.5) / MICRO_PER_CELL)
    return None


# Micro Trigonometry (user, 2026-10-17: "custom, distinct trigonometric
# offset settings for the micro coordinates ... very, super precise, where
# an inner coordinate can also shift a little bit here and there"). Its own
# settings, apart from the tag's on the Trigonometry card, all in
# millimetres on the board (inches for heights) and stepped finely:
#   - the parallax of the surface the gripper takes an object by: the camera
#     sees it MICRO_TRIG_GRIP_IN above the board, pushed away from the
#     camera's nadir, so it is pulled back toward the nadir by
#     k = (H - h)/H -- the tag's trigonometry, for the object;
#   - the nadir itself, from the board's middle;
#   - a shift of every micro coordinate, and shifts at 3 x 3 points over the
#     board blended between them -- here and there;
#   - where in its macro cell the gripper really comes down.
# A micro grip goes through micro_true_point, and micro_macro_cell picks the
# macro cell for it; the macro move itself (the tag to that cell, centred)
# is not changed.
MICRO_TRIG_STEP_MM = 0.5            # the finest step of a shift, mm
MICRO_TRIG_CAMERA_IN = 35.0         # the camera's height above the board
MICRO_TRIG_GRIP_IN = 0.5            # the gripped surface's height above it
MICRO_TRIG_NADIR_MM = [0.0, 0.0]    # below the camera, from the board's middle (right, down)
MICRO_TRIG_SHIFT_MM = [0.0, 0.0]    # every micro coordinate (right, down)
MICRO_TRIG_LAND_MM = [0.0, 0.0]     # the gripper's landing, from its macro cell's middle
# the 3 x 3 points, row by row from the top-left: the board's corners, the
# middles of its edges and its middle
MICRO_TRIG_POINTS = ("top-left", "top", "top-right", "left", "middle", "right",
                     "bottom-left", "bottom", "bottom-right")
MICRO_TRIG_LOCAL_MM = [[0.0, 0.0] for _ in MICRO_TRIG_POINTS]
MICRO_TRIG_LIMIT_MM = 40.0          # no shift or landing past this
MICRO_TRIG_NADIR_LIMIT_MM = 400.0


def micro_mm_per_cell() -> float:
    """A macro cell's side on the board, mm (the board's width over its columns)."""
    return max(1e-6, BOARD_WIDTH_IN * 25.4 / max(1, CONFIG.n_cols))


def micro_trig_k(height_in=None) -> float:
    """k = (H - h)/H for a surface `height_in` (the gripped one by default)
    above the board; 1.0 (no correction) for impossible numbers."""
    H = MICRO_TRIG_CAMERA_IN
    h = MICRO_TRIG_GRIP_IN if height_in is None else height_in
    if H <= 0 or h < 0 or h >= H:
        return 1.0
    return (H - h) / H


def micro_nadir() -> tuple:
    """The camera's nadir in grid units."""
    mm = micro_mm_per_cell()
    return (CONFIG.n_cols / 2.0 + MICRO_TRIG_NADIR_MM[0] / mm,
            CONFIG.n_rows / 2.0 + MICRO_TRIG_NADIR_MM[1] / mm)


def micro_trig_axis(n: int) -> tuple:
    """The 3 x 3 points' cells along one side of n cells: first, middle,
    last (A, K, T) -- the cells the card names them by."""
    return (0, n // 2, max(0, n - 1))


def _micro_bracket(v: float, n: int):
    """(i, fraction) between the points' cell MIDDLES along a side: each
    point's shift is exactly its setting at the middle of its cell, blended
    in a straight line between points, flat beyond the outer ones."""
    xs = [c + 0.5 for c in micro_trig_axis(n)]
    if v <= xs[0]:
        return 0, 0.0
    if v >= xs[2]:
        return 1, 1.0
    i = 0 if v < xs[1] else 1
    span = xs[i + 1] - xs[i]
    return i, ((v - xs[i]) / span if span > 0 else 0.0)


def micro_shift_at(col: float, row: float) -> tuple:
    """The fine shift at grid point (col, row), in cells: the shift of every
    micro coordinate plus the 3 x 3 local shifts, blended between the four
    points round it."""
    i, fu = _micro_bracket(col, CONFIG.n_cols)
    j, fv = _micro_bracket(row, CONFIG.n_rows)

    def at(a, b, axis):
        return MICRO_TRIG_LOCAL_MM[b * 3 + a][axis]

    mm = micro_mm_per_cell()
    out = []
    for axis in (0, 1):
        local = ((1 - fu) * (1 - fv) * at(i, j, axis) + fu * (1 - fv) * at(i + 1, j, axis)
                 + (1 - fu) * fv * at(i, j + 1, axis) + fu * fv * at(i + 1, j + 1, axis))
        out.append((MICRO_TRIG_SHIFT_MM[axis] + local) / mm)
    return out[0], out[1]


def micro_true_point(col: float, row: float, height_in=None) -> tuple:
    """A point of an object as the camera sees it (grid units, at the
    gripped surface's height) -> the board point it stands over, by the
    micro trigonometry: pulled toward the nadir by k, then shifted by the
    fine shifts there."""
    nx, ny = micro_nadir()
    k = micro_trig_k(height_in)
    x, y = nx + k * (col - nx), ny + k * (row - ny)
    sx, sy = micro_shift_at(x, y)
    return x + sx, y + sy


def micro_seen_point(col: float, row: float) -> tuple:
    """Where a point on the board itself shows in the camera's grid -- the
    inverse of micro_true_point on the board (no height): for drawing the
    micro grid and a grip where they are."""
    x, y = col, row
    for _ in range(80):             # until it settles (exact, even at the limits)
        sx, sy = micro_shift_at(x, y)
        nx, ny = col - sx, row - sy
        if abs(nx - x) < 1e-12 and abs(ny - y) < 1e-12:
            return nx, ny
        x, y = nx, ny
    return x, y


_MICRO_SEEN_CACHE = {"key": None, "points": {}}


def micro_seen_point_cached(col: float, row: float) -> tuple:
    """micro_seen_point, remembered until a Micro Trigonometry setting
    changes -- the Magnifier's micro grid asks for the same corners every
    frame."""
    key = micro_trig_key()
    cache = _MICRO_SEEN_CACHE
    if cache["key"] != key or len(cache["points"]) > 50000:
        cache["key"], cache["points"] = key, {}
    got = cache["points"].get((col, row))
    if got is None:
        got = cache["points"][(col, row)] = micro_seen_point(col, row)
    return got


def micro_trig_key() -> tuple:
    """Every Micro Trigonometry setting as one value: a drawing that depends
    on them is redrawn when this changes."""
    return (MICRO_TRIG_CAMERA_IN, MICRO_TRIG_GRIP_IN, tuple(MICRO_TRIG_NADIR_MM),
            tuple(MICRO_TRIG_SHIFT_MM), tuple(MICRO_TRIG_LAND_MM),
            tuple(tuple(p) for p in MICRO_TRIG_LOCAL_MM), BOARD_WIDTH_IN)


def micro_land_cells() -> tuple:
    """The gripper's landing offset in its macro cell, in cells."""
    mm = micro_mm_per_cell()
    return MICRO_TRIG_LAND_MM[0] / mm, MICRO_TRIG_LAND_MM[1] / mm


def micro_macro_cell(pt, reach=None) -> tuple:
    """The macro cell to send the gripper to for a grip at board point `pt`:
    the one whose landing point (its middle plus the landing offset) is
    nearest it -- the macro cell the micro point is in, when the gripper
    lands in the middle. With `reach` (c0, r0, c1, r1), the nearest one the
    gripper can reach."""
    lx, ly = micro_land_cells()
    c0, r0, c1, r1 = reach if reach else (0, 0, CONFIG.n_cols, CONFIG.n_rows)
    return (max(c0, min(c1 - 1, int(math.floor(pt[0] - lx)))),
            max(r0, min(r1 - 1, int(math.floor(pt[1] - ly)))))


def micro_landing(cell) -> tuple:
    """Where the gripper comes down for macro cell `cell`, grid units."""
    lx, ly = micro_land_cells()
    return cell[0] + 0.5 + lx, cell[1] + 0.5 + ly


def micro_trig_settings() -> dict:
    """The Micro Trigonometry settings, as save_settings keeps them."""
    return {"camera_in": MICRO_TRIG_CAMERA_IN, "grip_in": MICRO_TRIG_GRIP_IN,
            "nadir_mm": list(MICRO_TRIG_NADIR_MM),
            "shift_mm": list(MICRO_TRIG_SHIFT_MM),
            "land_mm": list(MICRO_TRIG_LAND_MM),
            "local_mm": [list(p) for p in MICRO_TRIG_LOCAL_MM]}


def load_micro_trig_settings(m):
    """The saved Micro Trigonometry settings; a value of the wrong kind or
    out of range keeps the default."""
    global MICRO_TRIG_CAMERA_IN, MICRO_TRIG_GRIP_IN
    if not isinstance(m, dict):
        return

    def number(v, lo, hi):
        return (isinstance(v, (int, float)) and not isinstance(v, bool)
                and math.isfinite(v) and lo <= v <= hi)

    def pair(v, limit):
        return (isinstance(v, (list, tuple)) and len(v) == 2
                and all(number(a, -limit, limit) for a in v))

    # the gripped surface at most half way up to the camera: past that the
    # parallax is nonsense
    cam = (round(float(m["camera_in"]), 2) if number(m.get("camera_in"), 1.0, 240.0)
           else MICRO_TRIG_CAMERA_IN)
    grip = (round(float(m["grip_in"]), 2) if number(m.get("grip_in"), 0.0, 20.0)
            else MICRO_TRIG_GRIP_IN)
    if grip <= cam / 2.0:
        MICRO_TRIG_CAMERA_IN, MICRO_TRIG_GRIP_IN = cam, grip
    for key, target, limit in (("nadir_mm", MICRO_TRIG_NADIR_MM, MICRO_TRIG_NADIR_LIMIT_MM),
                               ("shift_mm", MICRO_TRIG_SHIFT_MM, MICRO_TRIG_LIMIT_MM),
                               ("land_mm", MICRO_TRIG_LAND_MM, MICRO_TRIG_LIMIT_MM)):
        if pair(m.get(key), limit):
            target[:] = [round(float(a), 2) for a in m[key]]
    local = m.get("local_mm")
    if (isinstance(local, (list, tuple)) and len(local) == len(MICRO_TRIG_POINTS)
            and all(pair(p, MICRO_TRIG_LIMIT_MM) for p in local)):
        for k, p in enumerate(local):
            MICRO_TRIG_LOCAL_MM[k] = [round(float(a), 2) for a in p]


def build_path_commands(start_col: int, start_row: int, end_col: int, end_row: int):
    """Return the list of directional commands to walk from start to end,
    one grid cell at a time.

    VERTICAL FIRST, then horizontal, always -- never split across the two,
    never diagonal. The gantry's own hardware only ever runs one axis at a
    time (send_direction sends a single 'u'/'d'/'l'/'r' letter and the
    Arduino keeps running it until told otherwise), so this is not a
    display choice: it is the actual axis order the carriage moves in. All
    of the up/down commands come first, then all of the left/right ones --
    2026-09-26, the user's explicit correction: "do all the up-down first,
    and then right-left ... not half and half."

    Convention: row 0 is the TOP of the grid (row label '1'), so moving to a
    smaller row index is "up" and a larger row index is "down". Column 0 is
    the LEFT of the grid ('A'), so moving to a larger column index is
    "right" and a smaller one is "left".
    """
    commands = []

    col_diff = end_col - start_col
    row_diff = end_row - start_row

    vertical_cmd = "down" if row_diff > 0 else "up"
    for _ in range(abs(row_diff)):
        commands.append(vertical_cmd)

    horizontal_cmd = "right" if col_diff > 0 else "left"
    for _ in range(abs(col_diff)):
        commands.append(horizontal_cmd)

    return commands


def condense_commands(commands):
    """Turn ['right','right','down'] into a readable 'right x2, down x1'."""
    if not commands:
        return "(already there)"
    parts = []
    current = commands[0]
    count = 1
    for cmd in commands[1:]:
        if cmd == current:
            count += 1
        else:
            parts.append(f"{current} x{count}")
            current = cmd
            count = 1
    parts.append(f"{current} x{count}")
    return ", ".join(parts)


def _bgr(hex_colour: str):
    h = hex_colour.lstrip("#")
    r, g, b = int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)
    return (b, g, r)


ANIM_RATE = 0.35


def ease_toward(current: float, target: float, rate: float = ANIM_RATE) -> float:
    """One frame's step of `current` toward `target`.

    Every popover/panel in the app used to just appear and disappear -- a
    hard cut every other part of the UI is glassy and rounded and softly
    shadowed. This is the one shared primitive that makes all of them ease
    in and out instead, called once per frame with nothing to store but the
    current value.
    """
    value = current + (target - current) * rate
    return target if abs(value - target) < 0.002 else value


# ChatGPT's light theme, as chatgpt.com's own markup and stylesheets set
# it (archived 2026-10-03, rendered in Chrome and read back with
# getComputedStyle): a #fcfcfc page under white cards, #0d0d0d ink,
# #5d5d5d / #8f8f8f secondary text, 10%-black hairlines, #f3f3f3 hovers,
# #e8e8e8 for what you sent, black pill buttons that hover to #212121 and
# outlined ones with a 20%-black edge. C_OVERLAY is for what is drawn ON
# the camera picture, where black would vanish: ChatGPT's blue.
C_BG        = _bgr("#fcfcfc")
C_CARD      = _bgr("#ffffff")
C_CARD_SOFT = _bgr("#f3f3f3")
C_BORDER    = _bgr("#e5e5e5")
C_DIVIDER   = _bgr("#ececec")
C_RULE      = _bgr("#e3e3e3")       # 10% black on the page: the panel's edge
C_TEXT      = _bgr("#0d0d0d")
C_TEXT_DIM  = _bgr("#5d5d5d")
C_TEXT_FAINT = _bgr("#8f8f8f")
C_ACCENT    = _bgr("#0d0d0d")
C_SELECTED  = _bgr("#ececec")
C_BUBBLE    = _bgr("#e8e8e8")
C_BUBBLE_EDGE = _bgr("#dcdcdc")     # its 5%-black edge
C_GREEN     = _bgr("#10a37f")
C_AMBER     = _bgr("#f59e0b")
C_RED       = _bgr("#d8241a")
C_BLUE      = _bgr("#0385ff")
C_OVERLAY   = C_BLUE
C_ERROR_TEXT = _bgr("#ba2623")
C_ERROR_BG  = _bgr("#fff1f0")
C_SWITCH_OFF = _bgr("#e3e3e3")
C_BTN       = _bgr("#0d0d0d")
C_BTN_HOVER = _bgr("#212121")
C_BTN_FG    = _bgr("#ffffff")
C_GHOST     = _bgr("#ffffff")
C_GHOST_HOV = _bgr("#f3f3f3")
C_OUTLINE   = _bgr("#cccccc")       # 20% black: an outlined button's edge
C_COMPOSE   = _bgr("#f9f9f9")       # the prompt box's fill
C_SWITCH_TRACK = _bgr("#d6d6d6")    # an off switch's track

# Light and dark mode, switched by the sun/moon toggle in the top bar
# (user, 2026-10-18). Dark is ChatGPT's dark theme: a #212121 page, #303030
# surfaces, #ececec ink, white pill buttons with black text.
THEMES = {
    "light": {name: globals()[name] for name in (
        "C_BG", "C_CARD", "C_CARD_SOFT", "C_BORDER", "C_DIVIDER", "C_RULE",
        "C_TEXT", "C_TEXT_DIM", "C_TEXT_FAINT", "C_ACCENT", "C_SELECTED",
        "C_BUBBLE", "C_BUBBLE_EDGE", "C_ERROR_TEXT", "C_ERROR_BG",
        "C_SWITCH_OFF", "C_BTN", "C_BTN_HOVER", "C_BTN_FG", "C_GHOST",
        "C_GHOST_HOV", "C_OUTLINE", "C_COMPOSE", "C_SWITCH_TRACK")},
    "dark": {
        "C_BG": _bgr("#212121"), "C_CARD": _bgr("#2a2a2a"),
        "C_CARD_SOFT": _bgr("#303030"), "C_BORDER": _bgr("#3a3a3a"),
        "C_DIVIDER": _bgr("#363636"), "C_RULE": _bgr("#383838"),
        "C_TEXT": _bgr("#ececec"), "C_TEXT_DIM": _bgr("#b4b4b4"),
        "C_TEXT_FAINT": _bgr("#8f8f8f"), "C_ACCENT": _bgr("#ececec"),
        "C_SELECTED": _bgr("#424242"), "C_BUBBLE": _bgr("#303030"),
        "C_BUBBLE_EDGE": _bgr("#3d3d3d"), "C_ERROR_TEXT": _bgr("#ff6b62"),
        "C_ERROR_BG": _bgr("#3a2120"), "C_SWITCH_OFF": _bgr("#4a4a4a"),
        "C_BTN": _bgr("#ffffff"), "C_BTN_HOVER": _bgr("#e3e3e3"),
        "C_BTN_FG": _bgr("#0d0d0d"), "C_GHOST": _bgr("#212121"),
        "C_GHOST_HOV": _bgr("#303030"), "C_OUTLINE": _bgr("#4d4d4d"),
        "C_COMPOSE": _bgr("#303030"), "C_SWITCH_TRACK": _bgr("#4a4a4a")},
}
THEME = "light"
_THEME_HOOKS = []     # caches other parts of HOS X drop when the theme changes


def apply_theme(name):
    """Swap every palette colour to `name`'s and forget the drawings
    recorded in the old ones."""
    global THEME
    if name not in THEMES:
        return
    THEME = name
    globals().update(THEMES[name])
    for cache in ("_CARD_STAMPS", "_SHADOW_STAMPS", "_BUTTON_STAMPS"):
        if cache in globals():
            globals()[cache].clear()
    for hook in _THEME_HOOKS:
        try:
            hook()
        except Exception:
            pass


def css_baseline(px, line_h):
    """Where CSS puts the baseline of SF Pro text `px` high in a line box
    `line_h` tall, from the box's top: the font's ascent under half the
    leading -- ascent and descent (hhea: 1980/432 per 2048) rounded to whole
    pixels, the half-leading floored, as Blink lays a line out."""
    asc = math.floor(px * 1980 / 2048 + 0.5)
    desc = math.floor(px * 432 / 2048 + 0.5)
    return float(asc + math.floor((line_h - (asc + desc)) / 2.0))


BUTTON_SPACING = -0.08      # ChatGPT's buttons: letter-spacing -0.08px


FONT = cv2.FONT_HERSHEY_SIMPLEX

GLASS_ALPHA = 0.10


def blur_band(frame, a, b, c, d):
    """Gaussian-blur one rectangular region of `frame` in place, (a,b)-(c,d).

    Used to knock the room out of focus around the board so the grid reads
    as the one thing in the shot worth looking at. A no-op on an empty or
    inverted rect; the kernel is capped to the band's own smaller side so a
    sliver strip (the board dragged to the very edge of the frame) never
    hands cv2 a kernel bigger than the pixels it is blurring.

    Downsampled first, the same way glass_card blurs a panel's backdrop --
    at full resolution this ran a 45px-kernel GaussianBlur over up to the
    whole frame, four times, every frame: ~43ms on a 2000x1200 canvas, on
    its own most of a frame's entire budget at 60fps and the single biggest
    thing slowing down how quickly a click's own result reached the screen.
    A blurred-out background band has no fine detail for the downsample to
    lose, so the result looks the same at a fraction of the cost.
    """
    if b >= d or a >= c:
        return
    band = frame[b:d, a:c]
    bh, bw = d - b, c - a
    k = min(45, bh | 1, bw | 1)
    if k < 3:
        return
    sw, sh = max(1, bw // 8), max(1, bh // 8)
    # Shrink from a whole number of 8x8 blocks: INTER_AREA then takes its
    # integer fast path (~7x quicker than the general one on a 525x1013
    # band). The few rows/columns left over at the edge are still covered
    # by the stretch back up -- there is no detail to lose in a blur.
    src = band[:sh * 8, :sw * 8] if bw >= 8 and bh >= 8 else band
    small = cv2.resize(src, (sw, sh), interpolation=cv2.INTER_AREA)
    sk = min(k // 8 | 1, sw | 1, sh | 1)
    if sk >= 3:
        small = cv2.GaussianBlur(small, (sk, sk), 0)
    frame[b:d, a:c] = cv2.resize(small, (bw, bh), interpolation=cv2.INTER_LINEAR)


_CARD_STAMPS = {}


def glass_card(img, rect, radius, alpha=GLASS_ALPHA, blur=True, shadow=True):
    """A floating pane, the way ChatGPT draws its menus and dialogs: an
    opaque white card, a 10%-black hairline and a faint neutral shadow.

    (The name and the alpha/blur arguments are from when panels were
    frosted glass; ChatGPT's are solid, so both are accepted and ignored.)
    The card and its edge are an AffineStamp per size.
    """
    if shadow:
        drop_shadow(img, rect, radius, spread=16, strength=0.20)
    rx0, ry0, rx1, ry1 = (int(round(v)) for v in rect)
    if rx1 <= rx0 or ry1 <= ry0:
        return
    key = (rx1 - rx0, ry1 - ry0, int(radius))
    stamp = _CARD_STAMPS.get(key)
    if stamp is None:
        if len(_CARD_STAMPS) >= 64:
            _CARD_STAMPS.clear()
        cw, ch = rx1 - rx0, ry1 - ry0

        def paint(im):
            css_rect(im, (3, 3, 3 + cw, 3 + ch), radius, C_CARD, C_BORDER)

        stamp = _CARD_STAMPS[key] = AffineStamp(cw + 7, ch + 7, paint)
    stamp.apply(img, rx0 - 3, ry0 - 3)


def rounded_rect(img, rect, radius, colour, thickness=-1, alpha=1.0,
                 clip=None):
    """Filled or stroked rounded rectangle, optionally blended.

    A blended shape is composed on a copy of its OWN region, not of the whole
    image: every card, button and shadow ring on this canvas is small, and
    copying the full frame per ring cost more than the rest of the UI put
    together. `clip` narrows that region further, so a caller can commit only
    the part of the shape it will actually leave visible; it applies to
    blended shapes only.
    """
    x0, y0, x1, y1 = (int(round(v)) for v in rect)
    if x1 <= x0 or y1 <= y0:
        return
    r = int(max(0, min(radius, (x1 - x0) // 2, (y1 - y0) // 2)))
    blend = alpha < 0.999

    if blend:
        h, w = img.shape[:2]
        pad = max(2, int(thickness)) if thickness > 0 else 1
        rx0, ry0 = max(0, x0 - pad), max(0, y0 - pad)
        rx1, ry1 = min(w, x1 + pad + 1), min(h, y1 + pad + 1)
        if clip is not None:
            cx0, cy0, cx1, cy1 = (int(round(v)) for v in clip)
            rx0, ry0 = max(rx0, cx0), max(ry0, cy0)
            rx1, ry1 = min(rx1, cx1), min(ry1, cy1)
        if rx1 <= rx0 or ry1 <= ry0:
            return
        base = img[ry0:ry1, rx0:rx1].copy()
        layer = base.copy()
        x0, y0, x1, y1 = x0 - rx0, y0 - ry0, x1 - rx0, y1 - ry0
    else:
        layer = img

    if thickness < 0:
        if r:
            cv2.rectangle(layer, (x0 + r, y0), (x1 - r, y1), colour, -1, cv2.LINE_AA)
            cv2.rectangle(layer, (x0, y0 + r), (x1, y1 - r), colour, -1, cv2.LINE_AA)
            for cx, cy in ((x0 + r, y0 + r), (x1 - r, y0 + r),
                           (x0 + r, y1 - r), (x1 - r, y1 - r)):
                cv2.circle(layer, (cx, cy), r, colour, -1, cv2.LINE_AA)
        else:
            cv2.rectangle(layer, (x0, y0), (x1, y1), colour, -1, cv2.LINE_AA)
    else:
        t = thickness
        cv2.line(layer, (x0 + r, y0), (x1 - r, y0), colour, t, cv2.LINE_AA)
        cv2.line(layer, (x0 + r, y1), (x1 - r, y1), colour, t, cv2.LINE_AA)
        cv2.line(layer, (x0, y0 + r), (x0, y1 - r), colour, t, cv2.LINE_AA)
        cv2.line(layer, (x1, y0 + r), (x1, y1 - r), colour, t, cv2.LINE_AA)
        for (cx, cy), ang in (((x0 + r, y0 + r), 180), ((x1 - r, y0 + r), 270),
                              ((x1 - r, y1 - r), 0), ((x0 + r, y1 - r), 90)):
            cv2.ellipse(layer, (cx, cy), (r, r), ang, 0, 90, colour, t, cv2.LINE_AA)

    if blend:
        img[ry0:ry1, rx0:rx1] = cv2.addWeighted(layer, alpha, base, 1 - alpha, 0)


def _box_coverage(w, h, x0, y0, x1, y1, r):
    """Coverage, over a w x h grid, of a box with edges at x0..x1, y0..y1
    (pixel edges, not centres) and corner radius r: exact along its straight
    edges, analytic on its corners."""
    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32)
    xs += 0.5
    ys += 0.5
    bx, by = (x1 - x0) / 2.0, (y1 - y0) / 2.0
    r = max(0.0, min(r, bx, by))
    qx = np.abs(xs - (x0 + x1) / 2.0) - (bx - r)
    qy = np.abs(ys - (y0 + y1) / 2.0) - (by - r)
    d = (np.hypot(np.maximum(qx, 0), np.maximum(qy, 0))
         + np.minimum(np.maximum(qx, qy), 0) - r)
    return np.clip(0.5 - d, 0.0, 1.0)


def css_rect(img, rect, radius, fill=None, border=None, alpha=1.0):
    """A CSS box as a browser paints it: `rect` (x0, y0, x1, y1) as edges,
    snapped to whole pixels the way Blink snaps a box for painting, crisp
    along its sides, anti-aliased only on its `radius` corners; `fill`
    under, `border` as its outermost 1px ring.

    Only the rounded ends need the coverage maths, and that is cached per
    radius. The straight parts are plain fills: the same picture at a
    fraction of the cost (a full-height panel used to take 80 ms; user,
    2026-10-27). For whole and half-pixel radii it is the same pixel for
    pixel. Another fractional radius can differ by one level on a straight
    edge, where the old maths fell a hair short of full coverage."""
    snap = lambda v: int(math.floor(v + 0.5))
    x0, y0, x1, y1 = (snap(v) for v in rect)
    if x1 <= x0 or y1 <= y0:
        return
    r = max(0.0, min(float(radius), (x1 - x0) / 2.0, (y1 - y0) / 2.0))
    k = int(math.ceil(r)) + 1
    wide = x1 - x0 >= 2 * k + 2
    tall = y1 - y0 >= 2 * k + 2
    box = (x0, y0, x1, y1)

    def exact(window):
        _css_rect_exact(img, box, radius, fill, border, alpha, window=window)

    if wide and tall:
        for px, py in ((x0, y0), (x1 - k, y0), (x0, y1 - k), (x1 - k, y1 - k)):
            exact((px, py, px + k, py + k))
        inside = ((x0 + k, y0 + 1, x1 - k, y1 - 1), (x0 + 1, y0 + k, x0 + k, y1 - k),
                  (x1 - k, y0 + k, x1 - 1, y1 - k))
        ring = ((x0 + k, y0, x1 - k, y0 + 1), (x0 + k, y1 - 1, x1 - k, y1),
                (x0, y0 + k, x0 + 1, y1 - k), (x1 - 1, y0 + k, x1, y1 - k))
    elif wide:
        exact((x0, y0, x0 + k, y1))
        exact((x1 - k, y0, x1, y1))
        inside = ((x0 + k, y0 + 1, x1 - k, y1 - 1),)
        ring = ((x0 + k, y0, x1 - k, y0 + 1),)
        if y1 - y0 >= 2:
            ring += ((x0 + k, y1 - 1, x1 - k, y1),)
    elif tall:
        exact((x0, y0, x1, y0 + k))
        exact((x0, y1 - k, x1, y1))
        inside = ((x0 + 1, y0 + k, x1 - 1, y1 - k),)
        ring = ((x0, y0 + k, x0 + 1, y1 - k),)
        if x1 - x0 >= 2:
            ring += ((x1 - 1, y0 + k, x1, y1 - k),)
    else:
        exact(None)
        return
    # The inside: fill only. The outer 1px ring: fill, then border.
    for part in inside:
        _css_flat(img, part, fill, None, alpha)
    for part in ring:
        _css_flat(img, part, fill, border, alpha)


def _css_flat(img, box, fill, border, alpha):
    """A straight part of a css_rect, where the coverage is 1: the fill and
    then the border at `alpha`, blended and rounded once, like the corners."""
    if fill is None and border is None:
        return
    H, W = img.shape[:2]
    x0, y0, x1, y1 = max(0, box[0]), max(0, box[1]), min(W, box[2]), min(H, box[3])
    if x1 <= x0 or y1 <= y0:
        return
    if alpha >= 1.0:
        top = border if border is not None else fill
        colour = tuple(int(math.floor(float(c) + 0.5)) for c in top)
        cv2.rectangle(img, (x0, y0), (x1 - 1, y1 - 1), colour, -1)
        return
    roi = img[y0:y1, x0:x1]
    f = roi.astype(np.float32)
    a = np.float32(alpha)
    if fill is not None:
        f += (np.asarray(fill, np.float32) - f) * a
    if border is not None:
        f += (np.asarray(border, np.float32) - f) * a
    roi[:] = (f + 0.5).astype(np.uint8)


_COVERAGE_CACHE = {}


def _box_coverage_cached(w, h, x0, y0, x1, y1, r):
    key = (w, h, x0, y0, x1, y1, float(r))
    got = _COVERAGE_CACHE.get(key)
    if got is None:
        if len(_COVERAGE_CACHE) > 4096:
            _COVERAGE_CACHE.clear()
        got = _box_coverage(w, h, x0, y0, x1, y1, r)
        got.setflags(write=False)
        _COVERAGE_CACHE[key] = got
    return got


def _css_rect_exact(img, rect, radius, fill=None, border=None, alpha=1.0, window=None):
    """css_rect with the coverage maths over the whole box, or only over
    `window` (x0, y0, x1, y1) of it."""
    snap = lambda v: int(math.floor(v + 0.5))
    x0, y0, x1, y1 = (snap(v) for v in rect)
    H, W = img.shape[:2]
    rx0, ry0, rx1, ry1 = max(0, x0), max(0, y0), min(W, x1), min(H, y1)
    if window is not None:
        rx0, ry0 = max(rx0, window[0]), max(ry0, window[1])
        rx1, ry1 = min(rx1, window[2]), min(ry1, window[3])
        # A window on one side of the centre does not see the far edge, so
        # the far edge is moved to a fixed place and the maths is shared.
        # Only along a side long enough not to limit the radius.
        need = int(math.ceil(radius)) + 1
        if x1 - x0 >= 2 * radius:
            if 2 * rx1 <= x0 + x1:
                x1 = x0 + 2 * max(rx1 - x0 + 1, need)
            elif 2 * rx0 >= x0 + x1:
                x0 = x1 - 2 * max(x1 - rx0 + 1, need)
        if y1 - y0 >= 2 * radius:
            if 2 * ry1 <= y0 + y1:
                y1 = y0 + 2 * max(ry1 - y0 + 1, need)
            elif 2 * ry0 >= y0 + y1:
                y0 = y1 - 2 * max(y1 - ry0 + 1, need)
    if rx1 <= rx0 or ry1 <= ry0:
        return
    w, h = rx1 - rx0, ry1 - ry0
    outer = _box_coverage_cached(w, h, x0 - rx0, y0 - ry0, x1 - rx0, y1 - ry0, radius)
    roi = img[ry0:ry1, rx0:rx1]
    f = roi.astype(np.float32)
    if fill is not None:
        a = (outer * alpha)[..., None]
        f += (np.asarray(fill, np.float32) - f) * a
    if border is not None:
        inner = _box_coverage_cached(w, h, x0 - rx0 + 1, y0 - ry0 + 1, x1 - rx0 - 1,
                                     y1 - ry0 - 1, max(0.0, radius - 1))
        a = (np.clip(outer - inner, 0.0, 1.0) * alpha)[..., None]
        f += (np.asarray(border, np.float32) - f) * a
    roi[:] = (f + 0.5).astype(np.uint8)


class AffineStamp:
    """A drawing that only ever blends pixels toward fixed colours, recorded
    once and replayed as two whole-region cv2 calls.

    Everything that is "paint this colour over what is there, at this
    coverage" -- shadows, translucent fills, anti-aliased lines and text --
    leaves each pixel as  old * m + b  for an m and b that depend only on the
    pixel's position, never on the picture underneath. Drawing it once onto
    an all-black and once onto an all-white image recovers b and m exactly
    (up to the original's own rounding), and replaying is then one
    cv2.multiply and one cv2.add over the stamp's box instead of re-running
    every ring, blend and glyph. Nothing that reads neighbouring pixels (a
    blur) may be recorded this way.
    """

    __slots__ = ("pieces",)

    def __init__(self, w, h, draw, hole=None):
        """`draw(img)` paints the stamp into a (h, w, 3) uint8 image.

        `hole` (x0, y0, x1, y1), when given, is a part the drawing leaves
        untouched -- a shadow's card -- and is not stored or replayed: only
        the bands around it are.
        """
        w, h = int(w), int(h)
        black = np.zeros((h, w, 3), np.uint8)
        white = np.full((h, w, 3), 255, np.uint8)
        draw(black)
        draw(white)
        m = cv2.subtract(white, black)
        changed = ((m != 255) | (black != 0)).any(axis=2).astype(np.uint8)
        if hole is None:
            areas = [(0, 0, w, h)]
        else:
            hx0, hy0, hx1, hy1 = (max(0, min(lim, int(v))) for v, lim in
                                  zip(hole, (w, h, w, h)))
            areas = [(0, 0, w, hy0), (0, hy1, w, h),
                     (0, hy0, hx0, hy1), (hx1, hy0, w, hy1)]
            changed[hy0:hy1, hx0:hx1] = 0
        self.pieces = []
        for ax0, ay0, ax1, ay1 in areas:
            if ax1 <= ax0 or ay1 <= ay0:
                continue
            touched = cv2.findNonZero(changed[ay0:ay1, ax0:ax1])
            if touched is None:
                continue
            bx, by, bw, bh = cv2.boundingRect(touched)
            bx, by = bx + ax0, by + ay0
            self.pieces.append((
                bx, by, bw, bh,
                np.ascontiguousarray(m[by:by + bh, bx:bx + bw]),
                np.ascontiguousarray(black[by:by + bh, bx:bx + bw])))

    def apply(self, img, x, y):
        """Replay with the stamp's top-left at (x, y), clipped to `img`."""
        ih, iw = img.shape[:2]
        for dx, dy, pw, ph, m, b in self.pieces:
            px, py = x + dx, y + dy
            x0, y0 = max(0, px), max(0, py)
            x1, y1 = min(iw, px + pw), min(ih, py + ph)
            if x1 <= x0 or y1 <= y0:
                continue
            sx0, sy0 = x0 - px, y0 - py
            sx1, sy1 = sx0 + (x1 - x0), sy0 + (y1 - y0)
            region = img[y0:y1, x0:x1]
            out = cv2.multiply(region, m[sy0:sy1, sx0:sx1], scale=1.0 / 255.0)
            cv2.add(out, b[sy0:sy1, sx0:sx1], dst=region)


_SHADOW_STAMPS = {}
_BUTTON_STAMPS = {}
SHADOW_SOFTEN = 0.32
BUTTON_STAMP_CACHE = 512
SHADOW_STAMP_CACHE = 256
SHADOW_STAMP_MAX_PIXELS = 3_000_000


def drop_shadow(img, rect, radius, spread=10, strength=0.16):
    """A few expanding translucent rings under a card -- cheap soft shadow.

    Only the band outside the card's box inset by its radius is committed:
    the caller paints the card over the rest immediately afterwards, and
    blending a full card-sized ring per step is by far the most expensive
    thing on this canvas.

    The rings depend only on the card's size, so they are worked out once per
    size (see AffineStamp) and every later shadow of that size is two cv2
    calls: a button's shadow went from 28 small blends to 2.
    """
    x0, y0, x1, y1 = (int(round(v)) for v in rect)
    if x1 <= x0 or y1 <= y0:
        return
    m = int(spread) + 6
    w, h = x1 - x0, y1 - y0
    if (w + 2 * m) * (h + 2 * m) > SHADOW_STAMP_MAX_PIXELS:
        _draw_shadow_rings(img, (x0, y0, x1, y1), radius, spread, strength)
        return
    key = (w, h, int(radius), int(spread), round(float(strength), 4))
    stamp = _SHADOW_STAMPS.get(key)
    if stamp is None:
        if len(_SHADOW_STAMPS) >= SHADOW_STAMP_CACHE:
            _SHADOW_STAMPS.clear()
        r = _shadow_inset(w, h, radius)
        stamp = _remember(_SHADOW_STAMPS, key, AffineStamp(
            w + 2 * m, h + 2 * m,
            lambda im: _draw_shadow_rings(im, (m, m, m + w, m + h), radius,
                                          spread, strength),
            hole=(m + r, m + r, m + w - r, m + h - r)))
    stamp.apply(img, x0 - m, y0 - m)


def _shadow_inset(w, h, radius):
    """How far in from a card's edges its rounded corners reach: inside
    the box inset by this much the card covers everything."""
    return int(max(0, min(radius, w // 2, h // 2)))


def _draw_shadow_rings(img, rect, radius, spread, strength):
    """The rings themselves: everywhere outside the card's box inset by
    its radius -- so into the rounded corners the card leaves bare, and
    under its straight edges, which the caller paints over."""
    x0, y0, x1, y1 = (int(round(v)) for v in rect)
    r = _shadow_inset(x1 - x0, y1 - y0, radius)
    ix0, iy0, ix1, iy1 = x0 + r, y0 + r, x1 - r, y1 - r
    # ChatGPT's elevation is a faint neutral shadow (0 4px 16px #0000000d
    # for menus): black, and about a third as strong as the old tinted one.
    colour = (0, 0, 0)
    for i in range(spread, 0, -2):
        a = SHADOW_SOFTEN * strength * (1.0 - (i - 1) / float(spread)) ** 1.8
        if a <= 0.004:
            continue
        ring = (x0 - i, y0 - i + 3, x1 + i, y1 + i + 3)
        for clip in ((x0 - i - 2, y0 - i, x1 + i + 2, iy0),
                     (x0 - i - 2, iy1, x1 + i + 2, y1 + i + 5),
                     (x0 - i - 2, iy0, ix0, iy1),
                     (ix1, iy0, x1 + i + 2, iy1)):
            rounded_rect(img, ring, radius + i, colour, -1, alpha=a, clip=clip)


VIDEO_RADIUS = 24


def _corner_alpha(r):
    """Coverage for one rounded corner block, its curve centred at (r, r)."""
    m = np.zeros((r, r), np.float32)
    cv2.circle(m, (r, r), r, 1.0, -1, cv2.LINE_AA)
    return m[..., None]


_CORNER_A = _corner_alpha(VIDEO_RADIUS)


def round_video_corners(canvas, wash, x, y, w, h, r=VIDEO_RADIUS):
    """Round the corners of a pane already pasted square onto the canvas.

    Only the four r-by-r corner blocks are touched, each blended back toward
    the background that was behind it -- 4 * 22 * 22 pixels instead of the
    whole pane, which is the difference between rounding these corners for
    free and paying a frame-sized float32 composite to do it.
    """
    if w < 2 * r or h < 2 * r:
        return
    for by, bx, a in ((y, x, _CORNER_A),
                      (y, x + w - r, _CORNER_A[:, ::-1]),
                      (y + h - r, x, _CORNER_A[::-1, :]),
                      (y + h - r, x + w - r, _CORNER_A[::-1, ::-1])):
        fg = canvas[by:by + r, bx:bx + r].astype(np.float32)
        bg = wash[by:by + r, bx:bx + r].astype(np.float32)
        canvas[by:by + r, bx:bx + r] = (fg * a + bg * (1.0 - a)).astype(np.uint8)


ASCII_MAP = str.maketrans({
    "\u00b0": " deg", "\u00d7": "x", "\u2013": "-", "\u2014": "--",
    "\u2212": "-", "\u00b7": "-", "\u2022": "-", "\u2026": "...",
    "\u2192": "->", "\u2190": "<-", "\u2191": "^", "\u2193": "v",
    "\u2713": "OK", "\u2018": "'", "\u2019": "'", "\u201c": '"',
    "\u201d": '"', "\u00a0": " ",
})


def ascii_text(label) -> str:
    """Whatever came in, rendered with characters this font actually has."""
    text = str(label).translate(ASCII_MAP)
    if text.isascii():
        return text
    return "".join(ch if ch.isascii() else "?" for ch in text)


_TEXT_CACHE_MAX = 20000
_TEXT_SIZES = {}
_WRAPS = {}
_FITS = {}


def _remember(cache, key, value):
    """Store one memoised layout result, emptying the cache when it gets big.

    Every one of these is a pure function of its arguments (one fixed font),
    so a hit is always right. Emptying instead of evicting one at a time keeps
    the hit path a single dict lookup.
    """
    if len(cache) >= _TEXT_CACHE_MAX:
        cache.clear()
    cache[key] = value
    return value


# Text is set in SF Pro -- the system font ChatGPT itself uses on a Mac --
# instead of OpenCV's built-in face. `scale` keeps its old meaning: SF Pro
# at scale * TEXT_PX_PER_SCALE px is as wide as the old font was, so every
# layout measured for the old text still fits. thickness 1 is Regular,
# 2 Semibold; `weight` picks any other (500 = ChatGPT's button Medium).
# `family` "a3" is Avenir Next, A3-Terra's face, for its message box.
# Each string is rendered once at TEXT_SS times the size and averaged down
# (unhinted, like CoreText draws), then kept; drawing is one small blend.
TEXT_PX_PER_SCALE = 25.0
TEXT_SS = 4
TEXT_GAMMA = 0.8          # CoreText's slightly heavier dark-on-light stems
TEXT_GAMMA_LIGHT = 0.6    # ...and its heavier light-on-dark ones
TEXT_GAMMA_UI = 0.9       # Chrome's "antialiased" SF Pro, as chatgpt.com
TEXT_GAMMA_UI_LIGHT = 1.0  # sets it: lighter than CoreText's own smoothing
UI_FONT_FILE = "/System/Library/Fonts/SFNS.ttf"
FONT_FACES = {
    "a3": {400: ("/System/Library/Fonts/Avenir Next.ttc", 7),
           500: ("/System/Library/Fonts/Avenir Next.ttc", 5),
           600: ("/System/Library/Fonts/Avenir Next.ttc", 2),
           700: ("/System/Library/Fonts/Avenir Next.ttc", 0)},
    "helvetica": {400: ("/System/Library/Fonts/Helvetica.ttc", 0),
                  700: ("/System/Library/Fonts/Helvetica.ttc", 1)},
    "lucida": {700: ("/System/Library/Fonts/LucidaGrande.ttc", 1)},
    "menlo": {700: ("/System/Library/Fonts/Menlo.ttc", 1)},
}
_FONT_OBJS = {}
_TEXT_MASKS = {}
_TEXT_FACES_OK = None


def _text_engine_ok():
    """True when Pillow and SF Pro are there; otherwise the old cv2 font."""
    global _TEXT_FACES_OK
    if _TEXT_FACES_OK is None:
        try:
            from PIL import ImageFont  # noqa: F401
            _TEXT_FACES_OK = os.path.exists(UI_FONT_FILE)
        except Exception:
            _TEXT_FACES_OK = False
    return _TEXT_FACES_OK


def _face(px, weight, family, ss=1):
    """A Pillow font for this size (1x px), weight and family, at ss times
    the size. SF Pro's optical size follows the size it is SHOWN at."""
    key = (family, px, weight, ss)
    f = _FONT_OBJS.get(key)
    if f is not None:
        return f
    from PIL import ImageFont
    faces = FONT_FACES.get(family)
    if faces:
        near = min(faces, key=lambda w: abs(w - weight))
        path, index = faces[near]
        if not os.path.exists(path):
            return _face(px, weight, "ui", ss)
        f = ImageFont.truetype(path, px * ss, index=index)
    else:
        f = ImageFont.truetype(UI_FONT_FILE, px * ss)
        try:
            f.set_variation_by_axes([100, max(17, min(96, px)), 400,
                                     max(1, min(1000, weight))])
        except Exception:
            pass
    if len(_FONT_OBJS) > 256:
        _FONT_OBJS.clear()
    _FONT_OBJS[key] = f
    return f


UI_MIN_PX = 12.0            # ChatGPT's smallest text (its "xs")
# Every text is set this much bigger than ChatGPT's measured sizes, so it
# is easy to read on the laptop's screen (user, 2026-10-28: "make the font
# size bigger", then "more text zoom"). Layout around it is unchanged;
# buttons widen to fit. Settings > Display > Text size changes it.
TEXT_ZOOM = 1.4
TEXT_ZOOM_RANGE = (1.0, 2.0)
TIP_LINE_H = round(20 * TEXT_ZOOM)
# Line heights that follow the text: (class name, attribute, at 100%).
_ZOOMED_LINES = (("AISidebar", "LINE_H", 24), ("AISidebar", "MENU_LINE_H", 20),
                 ("AISidebar", "USER_LINE_H", 21.75), ("AISidebar", "NOTE_H", 24),
                 ("ConsolePanel", "LINE_H", 20), ("GripperPanel", "NOTE_LINE_H", 18),
                 ("GripperPanel", "INSTR_LINE_H", 28))


def apply_text_zoom(zoom):
    """Set every text `zoom` times ChatGPT's size, now: the line heights
    follow, and every text measured or drawn at the old size is forgotten."""
    global TEXT_ZOOM, TIP_LINE_H
    lo, hi = TEXT_ZOOM_RANGE
    TEXT_ZOOM = round(min(hi, max(lo, float(zoom))), 2)
    TIP_LINE_H = round(20 * TEXT_ZOOM)
    for cls_name, attr, base in _ZOOMED_LINES:
        cls = globals().get(cls_name)
        if cls is not None:
            value = base * TEXT_ZOOM
            setattr(cls, attr, value if isinstance(base, float) else round(value))
    for cache in ("_TEXT_SIZES", "_WRAPS", "_FITS", "_TEXT_MASKS", "_UI_POSITIONS",
                  "_CARD_STAMPS", "_SHADOW_STAMPS", "_BUTTON_STAMPS"):
        if cache in globals():
            globals()[cache].clear()
    return TEXT_ZOOM


def _text_px(scale):
    return max(UI_MIN_PX * TEXT_ZOOM,
               round(float(scale) * TEXT_PX_PER_SCALE * TEXT_ZOOM * 4) / 4.0)


def _text_weight(thickness, weight):
    if weight:
        return int(weight)
    return 600 if thickness >= 2 else 400


# SF Pro as Chrome sets it for chatgpt.com: each glyph's advance at the
# optical size of its point size (opsz, 17 and up), plus the font's own
# tracking table for that size (-0.31px a glyph at 16px), plus its GPOS
# kerning, whose values move along the weight and optical-size axes. Read
# from the font file once with fontTools; without it, Pillow's spacing.
_UI_LAYOUT = {}
_UI_POSITIONS = {}
_UI_ADVANCES = {}
_UI_ADV_FONTS = {}
_UI_INSTANCERS = {}
_UI_KERNS = {}


def _ui_layout_info():
    if "info" in _UI_LAYOUT:
        return _UI_LAYOUT["info"]
    info = None
    try:
        import logging
        from fontTools.ttLib import TTFont
        logging.getLogger("fontTools").setLevel(logging.ERROR)
        font = TTFont(UI_FONT_FILE)
        try:
            info = {"upem": font["head"].unitsPerEm,
                    "cmap": dict(font.getBestCmap()),
                    "trak": sorted(font["trak"].horizData.get(0.0, {}).items())
                    if "trak" in font else [],
                    "axes": {a.axisTag: (a.minValue, a.defaultValue, a.maxValue)
                             for a in font["fvar"].axes},
                    "fvar_axes": font["fvar"].axes,
                    "avar": ({k: dict(v) for k, v in font["avar"].segments.items()}
                             if "avar" in font else {}),
                    "varstore": (getattr(font["GDEF"].table, "VarStore", None)
                                 if "GDEF" in font else None),
                    "lookups": []}
            try:
                info["lookups"] = _ui_kern_lookups(font)
            except Exception:
                info["lookups"] = []
        finally:
            font.close()
    except Exception:
        info = None
    _UI_LAYOUT["info"] = info
    return info


def _ui_kern_lookups(font):
    """The 'kern' feature's pair lookups: per lookup, its subtables in
    order, with a glyph -> coverage-index map each."""
    if "GPOS" not in font:
        return []
    gpos = font["GPOS"].table
    order = []
    for rec in gpos.FeatureList.FeatureRecord:
        if rec.FeatureTag == "kern":
            for li in rec.Feature.LookupListIndex:
                if li not in order:
                    order.append(li)
    lookups = []
    for li in order:
        lookup = gpos.LookupList.Lookup[li]
        subtables = []
        for st in lookup.SubTable:
            if lookup.LookupType == 9:
                if st.ExtensionLookupType != 2:
                    continue
                st = st.ExtSubTable
            elif lookup.LookupType != 2:
                continue
            cov = {g: i for i, g in enumerate(st.Coverage.glyphs)}
            if st.Format == 1:
                subtables.append((1, cov, st.PairSet, {}))
            elif st.Format == 2:
                subtables.append((2, cov, dict(st.ClassDef1.classDefs),
                                  dict(st.ClassDef2.classDefs),
                                  st.Class1Record))
        lookups.append(subtables)
    return lookups


def _ui_instancer(info, weight, opsz):
    key = (weight, opsz)
    inst = _UI_INSTANCERS.get(key)
    if inst is None and info["varstore"] is not None:
        from fontTools.varLib.models import normalizeLocation, piecewiseLinearMap
        from fontTools.varLib.varStore import VarStoreInstancer
        loc = normalizeLocation({"wght": weight, "opsz": opsz, "wdth": 100,
                                 "GRAD": 400}, info["axes"])
        for tag, mapping in info["avar"].items():
            if tag in loc:
                loc[tag] = piecewiseLinearMap(loc[tag], mapping)
        inst = _UI_INSTANCERS[key] = VarStoreInstancer(
            info["varstore"], info["fvar_axes"], loc)
    return inst


def _ui_kern(info, g1, g2, weight, opsz):
    """Font units the pair (g1, g2) is kerned by at this weight and
    optical size: per lookup, the first subtable covering g1 decides."""
    key = (g1, g2, weight, opsz)
    hit = _UI_KERNS.get(key)
    if hit is not None:
        return hit
    inst = _ui_instancer(info, weight, opsz)
    total = 0
    for subtables in info["lookups"]:
        for st in subtables:
            i = st[1].get(g1)
            if i is None:
                continue
            if st[0] == 1:
                rows = st[3].get(i)
                if rows is None:
                    rows = st[3][i] = {r.SecondGlyph: r.Value1
                                       for r in st[2][i].PairValueRecord}
                if g2 not in rows:
                    continue
                vr = rows[g2]
            else:
                vr = st[4][st[2].get(g1, 0)].Class2Record[st[3].get(g2, 0)].Value1
            if vr is not None:
                total += getattr(vr, "XAdvance", 0) or 0
                dev = getattr(vr, "XAdvDevice", None)
                if (inst is not None and dev is not None
                        and getattr(dev, "DeltaFormat", 0) == 0x8000):
                    total += inst[(dev.StartSize << 16) + dev.EndSize]
            break
    return _remember(_UI_KERNS, key, total)


def _ui_track(info, px):
    """SF's tracking for `px`, in px a glyph: its trak table, interpolated."""
    table = info["trak"]
    if not table:
        return 0.0
    if px <= table[0][0]:
        v = table[0][1]
    elif px >= table[-1][0]:
        v = table[-1][1]
    else:
        for (a, va), (b, vb) in zip(table, table[1:]):
            if a <= px <= b:
                v = va + (vb - va) * (px - a) / float(b - a)
                break
    return v * px / float(info["upem"])


def _ui_advance(ch, px, weight, opsz):
    key = (ch, px, weight)
    adv = _UI_ADVANCES.get(key)
    if adv is None:
        font = _UI_ADV_FONTS.get((weight, opsz))
        if font is None:
            from PIL import ImageFont
            font = ImageFont.truetype(UI_FONT_FILE, 2048)
            try:
                font.set_variation_by_axes([100, opsz, 400,
                                            max(1, min(1000, weight))])
            except Exception:
                pass
            _UI_ADV_FONTS[(weight, opsz)] = font
        adv = _remember(_UI_ADVANCES, key, font.getlength(ch) * px / 2048.0)
    return adv


def _ui_positions(text, px, weight, spacing=0.0):
    """Where Chrome puts each character of `text` set in SF Pro at `px`
    and `weight` -- with CSS letter-spacing `spacing` after each one:
    len(text) + 1 offsets, the last the whole advance. None without the
    font's tables."""
    key = (text, px, weight, spacing)
    hit = _UI_POSITIONS.get(key)
    if hit is not None:
        return hit
    info = _ui_layout_info()
    if info is None:
        return None
    opsz = max(17.0, min(96.0, float(px)))
    track = _ui_track(info, px)
    scale = px / float(info["upem"])
    glyphs = [info["cmap"].get(ord(ch)) for ch in text]
    xs, x = [0.0], 0.0
    for i, ch in enumerate(text):
        x += _ui_advance(ch, px, weight, opsz) + track + spacing
        if i + 1 < len(text) and glyphs[i] and glyphs[i + 1]:
            x += _ui_kern(info, glyphs[i], glyphs[i + 1], weight, opsz) * scale
        xs.append(x)
    return _remember(_UI_POSITIONS, key, tuple(xs))



def _text_mask(text, px, weight, family, light, frac=0.0, spacing=0.0):
    """(coverage float32 HxWx1, dx, dy) for `text` with its baseline-left at
    the origin -- `frac` px right of it, for SF Pro set glyph by glyph:
    rendered at TEXT_SS x and area-averaged down."""
    key = (text, px, weight, family, light, frac, spacing)
    hit = _TEXT_MASKS.get(key)
    if hit is not None:
        return hit
    from PIL import Image, ImageDraw
    ss = TEXT_SS
    big = _face(px, weight, family, ss)
    x0, y0, x1, y1 = big.getbbox(text, anchor="ls")
    xs = _ui_positions(text, px, weight, spacing) if family == "ui" else None
    if xs is not None:
        # glyph by glyph where Chrome sets them, each at its quarter pixel
        pad = int(math.ceil(px)) * ss
        x0, x1 = -pad, int(math.ceil(xs[-1])) * ss + pad
    bx0, by0 = math.floor(x0 / ss) * ss, math.floor(y0 / ss) * ss
    bx1, by1 = math.ceil(x1 / ss) * ss, math.ceil(y1 / ss) * ss
    if bx1 <= bx0 or by1 <= by0:
        hit = (None, 0, 0)
    else:
        im = Image.new("L", (bx1 - bx0, by1 - by0), 0)
        if xs is None:
            ImageDraw.Draw(im).text((-bx0, -by0), text, font=big, fill=255,
                                    anchor="ls")
        else:
            draw = ImageDraw.Draw(im)
            for ch, x in zip(text, xs):
                if ch.isspace():
                    continue
                q = math.floor((frac + x + 1 / 64.0) * 4) * ss // 4
                draw.text((q - bx0, -by0), ch, font=big, fill=255, anchor="ls")
        a = np.asarray(im, np.float32) / 255.0
        a = cv2.resize(a, ((bx1 - bx0) // ss, (by1 - by0) // ss),
                       interpolation=cv2.INTER_AREA)
        if family == "ui":
            a = np.power(a, TEXT_GAMMA_UI_LIGHT if light else TEXT_GAMMA_UI)
        else:
            a = np.power(a, TEXT_GAMMA_LIGHT if light else TEXT_GAMMA)
        hit = (a[..., None], bx0 // ss, by0 // ss)
    if len(_TEXT_MASKS) >= _TEXT_CACHE_MAX:
        _TEXT_MASKS.clear()
    _TEXT_MASKS[key] = hit
    return hit


def text_size(label, scale, thickness=1, weight=None, family="ui"):
    """Pixel size of `label` -- (advance width, cap height) -- memoised.

    The sidebar alone used to ask for ~950 text sizes a frame -- every
    word of every message, re-wrapped on every frame -- which by itself was a
    good part of why a click took a visible moment to show.
    """
    key = (label if isinstance(label, str) else str(label), scale, thickness,
           weight, family)
    size = _TEXT_SIZES.get(key)
    if size is None:
        text = ascii_text(key[0])
        if _text_engine_ok():
            px, wt = _text_px(scale), _text_weight(thickness, weight)
            f = _face(px, wt, family, TEXT_SS)
            cap = -f.getbbox("H", anchor="ls")[1] / TEXT_SS
            xs = _ui_positions(text, px, wt) if family == "ui" else None
            width = xs[-1] if xs is not None else f.getlength(text) / TEXT_SS
            size = (int(round(width)), int(round(cap)))
        else:
            size = cv2.getTextSize(text, FONT, scale, thickness)[0]
        size = _remember(_TEXT_SIZES, key, size)
    return size


def draw_text(img, label, org, scale=0.5, colour=None, thickness=1,
              weight=None, family="ui", spacing=0.0):
    """`label` with its baseline-left at `org` (`spacing`: CSS
    letter-spacing, px, for SF Pro)."""
    if colour is None:
        colour = C_TEXT
    text = ascii_text(label)
    if not text:
        return
    if not _text_engine_ok():
        cv2.putText(img, text, (int(org[0]), int(org[1])), FONT, scale,
                    colour, thickness, cv2.LINE_AA)
        return
    light = (0.114 * colour[0] + 0.587 * colour[1] + 0.299 * colour[2]) > 150
    # SF Pro keeps the origin's fraction, to 1/64px, and sets each glyph on
    # its quarter pixel from there; the baseline rounds to a whole pixel.
    xi = math.floor(org[0])
    frac = round((org[0] - xi) * 64) / 64.0 if family == "ui" else 0.0
    if frac >= 1.0:
        xi, frac = xi + 1, 0.0
    if family != "ui":
        xi, frac = int(round(org[0])), 0.0
    a, dx, dy = _text_mask(text, _text_px(scale),
                           _text_weight(thickness, weight), family, light,
                           frac, spacing if family == "ui" else 0.0)
    if a is None:
        return
    x, y = int(xi) + dx, int(math.floor(org[1] + 0.5)) + dy
    h, w = a.shape[:2]
    H, W = img.shape[:2]
    x0, y0, x1, y1 = max(0, x), max(0, y), min(W, x + w), min(H, y + h)
    if x1 <= x0 or y1 <= y0:
        return
    sub = a[y0 - y:y1 - y, x0 - x:x1 - x]
    roi = img[y0:y1, x0:x1]
    f = roi.astype(np.float32)
    f += (np.asarray(colour, np.float32) - f) * sub
    roi[:] = (f + 0.5).astype(np.uint8)


def wrap_text(text, width, scale):
    """Greedy word wrap, measured with the font actually used to draw.

    Lives at module level because two different cards need it; AISidebar._wrap
    is a thin delegate so the sidebar's call sites read as they always did.
    Memoised: a message wraps the same way every frame it is on screen.
    """
    key = (str(text), width, scale)
    hit = _WRAPS.get(key)
    if hit is None:
        hit = _remember(_WRAPS, key, tuple(_wrap_text(key[0], width, scale)))
    return list(hit)


def _wrap_text(text, width, scale):
    lines = []
    for para in str(text).splitlines() or [""]:
        words, line = para.split(), ""
        if not words:
            lines.append("")
            continue
        for w in words:
            probe = f"{line} {w}".strip()
            if text_size(probe, scale, 1)[0] > width and line:
                lines.append(line)
                line = w
            else:
                line = probe
        lines.append(line)
    return lines or [""]


def fit_text(text, width, scale):
    """One line, truncated with "..." if it would overflow width.

    Lives at module level for the same reason as wrap_text: AISidebar._fit
    is a thin delegate so its call sites keep working unchanged. Memoised,
    and the cut point is found by bisection rather than one character at a
    time -- a long plan step used to cost a getTextSize per character it
    lost, every frame.
    """
    text = str(text)
    key = (text, width, scale)
    hit = _FITS.get(key)
    if hit is not None:
        return hit
    if text_size(text, scale, 1)[0] <= width:
        return _remember(_FITS, key, text)
    lo, hi = 0, len(text)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if text_size(text[:mid] + "...", scale, 1)[0] <= width:
            lo = mid
        else:
            hi = mid - 1
    return _remember(_FITS, key, text[:lo] + "...")


def text_advance(label, scale, thickness=1, weight=None, family="ui",
                 spacing=0.0):
    """The exact advance of `label`, fractions kept -- for centring."""
    text = ascii_text(label)
    if family == "ui" and _text_engine_ok():
        xs = _ui_positions(text, _text_px(scale), _text_weight(thickness, weight),
                           spacing)
        if xs is not None:
            return xs[-1]
    return float(text_size(label, scale, thickness, weight, family)[0])


def draw_text_centred(img, label, rect, scale=0.5, colour=None, thickness=1,
                      weight=None, family="ui", spacing=0.0):
    x0, y0, x1, y1 = rect
    w = text_advance(label, scale, thickness, weight, family, spacing)
    _, h = text_size(label, scale, thickness, weight, family)
    draw_text(img, label, (x0 + (x1 - x0 - w) / 2, y0 + (y1 - y0 + h) / 2),
              scale, colour, thickness, weight, family, spacing)


def button_width(label, outlined=False, scale=0.56):
    """A ChatGPT button's width for `label`: 12px of padding either side of
    its semibold label, and its 1px border both sides when it has one."""
    return (text_advance(display_label(label), scale, 1, weight=600,
                         spacing=BUTTON_SPACING) + 24 + (2 if outlined else 0))


def draw_check(img, centre, colour, size=5):
    """ChatGPT's check mark: a short stroke and a long one."""
    cx, cy = centre
    pts = np.array([(cx - size, cy), (cx - size // 3, cy + size - 1),
                    (cx + size + 1, cy - size + 1)], np.int32)
    cv2.polylines(img, [pts], False, colour, 2, cv2.LINE_AA)


def draw_chevron(img, centre, size, colour, thickness=2, up=False):
    cx, cy = centre
    dy = -size if up else size
    pts = [(cx - size, cy - dy // 2), (cx, cy + dy // 2), (cx + size, cy - dy // 2)]
    cv2.polylines(img, [np.array(pts, np.int32)], False, colour, thickness,
                  cv2.LINE_AA)


def draw_refresh_icon(img, centre, r, colour, thickness=2):
    """A clockwise circular arrow: an open ring, the head at the top."""
    cx, cy = centre
    start, end = -30, 260                  # degrees, clockwise from 3 o'clock
    cv2.ellipse(img, (cx, cy), (r, r), 0, start, end, colour, thickness,
                cv2.LINE_AA)
    a = math.radians(end)
    ex, ey = cx + r * math.cos(a), cy + r * math.sin(a)
    tx, ty = -math.sin(a), math.cos(a)     # the ring's clockwise direction
    nx, ny = math.cos(a), math.sin(a)      # outward
    h = max(3.0, r * 0.62)
    pts = [(ex + tx * h * 1.1, ey + ty * h * 1.1),
           (ex + nx * h, ey + ny * h),
           (ex - nx * h, ey - ny * h)]
    cv2.fillPoly(img, [np.array([(round(x), round(y)) for x, y in pts], np.int32)],
                 colour, cv2.LINE_AA)


@dataclass
class CameraSettings:
    """Software image adjustments applied to every grabbed frame."""
    zoom: float = 1.0
    brightness: int = 0
    contrast: float = 1.0
    saturation: float = 1.0
    sharpness: float = 0.0
    rotation: int = 0
    mirror: bool = False

    def apply(self, frame):
        """The adjusted frame, at the camera's own size (turned with it)."""
        frame = self._turn(frame)
        if self.zoom > 1.001:
            h, w = frame.shape[:2]
            x0, y0, cw, ch = self._zoom_crop(w, h)
            frame = cv2.resize(frame[y0:y0 + ch, x0:x0 + cw], (w, h),
                               interpolation=cv2.INTER_LINEAR)
        return self._tone(frame)

    def full_size(self, frame):
        """(w, h) of apply(frame): the camera's size, turned with it."""
        h, w = frame.shape[:2]
        return (h, w) if self.rotation in (90, 270) else (w, h)

    def fitted(self, frame, avail_w, avail_h):
        """apply(frame) scaled to fit (avail_w, avail_h) as fit_frame scales
        it -- but the zoom's crop is scaled once, straight to that size, and
        the tone work runs on the fitted pixels. apply() and then fit_frame()
        scaled the crop up to the camera's full size and straight back down,
        every camera frame on the UI thread: ~10 ms of each frame at 1920x1080
        and a 1.1x zoom, measured under the app's own load. Always a new
        array, never `frame` itself: the caller draws on it."""
        turned = self._turn(frame)
        h, w = turned.shape[:2]
        crop = turned
        if self.zoom > 1.001:
            x0, y0, cw, ch = self._zoom_crop(w, h)
            crop = turned[y0:y0 + ch, x0:x0 + cw]
        scale = min(avail_w / float(w), avail_h / float(h))
        if 0.999 < scale < 1.001:
            tw, th = w, h
        else:
            tw, th = max(1, int(w * scale)), max(1, int(h * scale))
        if (crop.shape[1], crop.shape[0]) != (tw, th):
            step = tw / float(crop.shape[1])
            crop = cv2.resize(crop, (tw, th), interpolation=(
                cv2.INTER_AREA if step < 0.5 else cv2.INTER_LINEAR))
        elif crop is frame:
            crop = frame.copy()
        return self._tone(crop)

    def _zoom_crop(self, w, h):
        """(x0, y0, w, h) of the zoom's centred crop of a w x h frame."""
        cw = max(8, int(w / self.zoom))
        ch = max(8, int(h / self.zoom))
        return (w - cw) // 2, (h - ch) // 2, cw, ch

    def _turn(self, frame):
        if self.rotation == 90:
            frame = cv2.rotate(frame, cv2.ROTATE_90_CLOCKWISE)
        elif self.rotation == 180:
            frame = cv2.rotate(frame, cv2.ROTATE_180)
        elif self.rotation == 270:
            frame = cv2.rotate(frame, cv2.ROTATE_90_COUNTERCLOCKWISE)
        if self.mirror:
            frame = cv2.flip(frame, 1)
        return frame

    def _tone(self, frame):
        if abs(self.contrast - 1.0) > 1e-3 or self.brightness != 0:
            frame = cv2.convertScaleAbs(frame, alpha=self.contrast,
                                        beta=self.brightness)

        if abs(self.saturation - 1.0) > 1e-3:
            hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV).astype(np.float32)
            hsv[:, :, 1] = np.clip(hsv[:, :, 1] * self.saturation, 0, 255)
            frame = cv2.cvtColor(hsv.astype(np.uint8), cv2.COLOR_HSV2BGR)

        if self.sharpness > 1e-3:
            blur = cv2.GaussianBlur(frame, (0, 0), 2.0)
            frame = cv2.addWeighted(frame, 1.0 + self.sharpness,
                                    blur, -self.sharpness, 0)

        return frame


# Camera names (user, 2026-10-18: "actual names for the cameras", not
# cam0/cam1). macOS knows each camera's own name ("FaceTime HD Camera",
# "Iriun Camera"); OpenCV numbers them by their unique ID, sorted, so the
# same sort gives each index its name.
_CAMERA_DEVICES = None


def camera_devices(refresh=False) -> list:
    """[(name, unique id)] in OpenCV's index order; [] when unknown."""
    global _CAMERA_DEVICES
    if _CAMERA_DEVICES is not None and not refresh:
        return _CAMERA_DEVICES
    found = []
    try:
        import AVFoundation as _av
        for d in _av.AVCaptureDevice.devicesWithMediaType_(_av.AVMediaTypeVideo) or ():
            found.append((str(d.localizedName()), str(d.uniqueID())))
    except Exception:
        found = []
    if not found and sys.platform == "darwin":
        try:
            out = subprocess.run(["system_profiler", "SPCameraDataType"],
                                 capture_output=True, text=True, timeout=8).stdout
            name = None
            for line in out.splitlines():
                t = line.strip()
                if t.endswith(":") and line.startswith("    ") and not line.startswith("      "):
                    name = t[:-1]
                elif t.startswith("Unique ID:") and name:
                    found.append((name, t.split(":", 1)[1].strip()))
                    name = None
        except Exception:
            found = []
    found.sort(key=lambda d: d[1])
    if found != _CAMERA_DEVICES:
        global CAMERA_LIST_VERSION
        CAMERA_LIST_VERSION += 1
    _CAMERA_DEVICES = found
    return found


# Bumped whenever a rescan finds a camera plugged in or out (user,
# 2026-11-02: "keep re-scanning for cameras without interrupting any
# view"). The UI rebuilds its camera lists when it changes.
CAMERA_LIST_VERSION = 0


def camera_name(index) -> str:
    """A camera's own name by OpenCV index; "Camera N" when not known. Two
    of the same name are told apart by their number."""
    devs = camera_devices()
    if isinstance(index, int) and 0 <= index < len(devs):
        name = devs[index][0]
        if sum(1 for n, _ in devs if n == name) > 1:
            name = f"{name} ({index})"
        return name
    return f"Camera {index}"


def camera_index_of(uid: str):
    """OpenCV index of the camera with this unique ID, or None."""
    for i, (_, u) in enumerate(camera_devices()):
        if u == uid:
            return i
    return None


def camera_id_at(index):
    """Unique ID of the camera at this OpenCV index, or None."""
    devs = camera_devices()
    if isinstance(index, int) and 0 <= index < len(devs):
        return devs[index][1]
    return None


class NativeCapture:
    """A camera read straight through AVFoundation, for the ones OpenCV
    cannot open (user, 2026-11-02: "not detecting all the cameras"). A UVC
    camera that offers only 160x120 ("Wed Camera") makes OpenCV's open
    throw, while macOS streams it fine. The same read()/isOpened()/release()
    as cv2.VideoCapture, so the grabber threads take either."""

    _queue = None

    def __init__(self, uid: str):
        self._cond = threading.Condition()
        self._frame, self._seq, self._read_seq = None, 0, 0
        self._session = None
        try:
            self._start(uid)
        except Exception as e:
            print(f"[camera] AVFoundation could not open {uid}: {e}")
            self._session = None

    @classmethod
    def _dispatch_queue(cls):
        if cls._queue is None:
            import ctypes
            import objc
            lib = ctypes.CDLL("/usr/lib/libSystem.dylib")
            lib.dispatch_queue_create.restype = ctypes.c_void_p
            lib.dispatch_queue_create.argtypes = [ctypes.c_char_p, ctypes.c_void_p]
            cls._queue = objc.objc_object(
                c_void_p=lib.dispatch_queue_create(b"hosx.camera", None))
        return cls._queue

    def _start(self, uid):
        import AVFoundation as _av
        import Quartz
        dev = _av.AVCaptureDevice.deviceWithUniqueID_(uid)
        if dev is None:
            return
        inp, err = _av.AVCaptureDeviceInput.deviceInputWithDevice_error_(dev, None)
        if inp is None:
            print(f"[camera] AVFoundation could not open {uid}: {err}")
            return
        session = _av.AVCaptureSession.alloc().init()
        if not session.canAddInput_(inp):
            return
        session.addInput_(inp)
        out = _av.AVCaptureVideoDataOutput.alloc().init()
        out.setVideoSettings_({Quartz.kCVPixelBufferPixelFormatTypeKey:
                               Quartz.kCVPixelFormatType_32BGRA})
        out.setAlwaysDiscardsLateVideoFrames_(True)
        self._delegate = _native_frame_delegate()(self)
        out.setSampleBufferDelegate_queue_(self._delegate, self._dispatch_queue())
        if not session.canAddOutput_(out):
            return
        session.addOutput_(out)
        session.startRunning()
        self._session = session

    def _deliver(self, frame):
        with self._cond:
            self._frame = frame
            self._seq += 1
            self._cond.notify_all()

    def isOpened(self):
        return self._session is not None

    def read(self):
        """The next frame (BGR), waiting up to 1 s for it like cv2 does."""
        if self._session is None:
            return False, None
        with self._cond:
            self._cond.wait_for(lambda: self._seq != self._read_seq, timeout=1.0)
            if self._frame is None or self._seq == self._read_seq:
                return False, None
            self._read_seq = self._seq
            return True, self._frame

    def release(self):
        if self._session is not None:
            self._session.stopRunning()
            self._session = None


_NATIVE_DELEGATE = None


def _native_frame_delegate():
    """The AVFoundation sample-buffer delegate class, made once (an
    Objective-C class can only be defined once per process)."""
    global _NATIVE_DELEGATE
    if _NATIVE_DELEGATE is not None:
        return _NATIVE_DELEGATE
    import CoreMedia
    import Quartz
    from Foundation import NSObject

    class HOSXFrameDelegate(NSObject):
        def captureOutput_didOutputSampleBuffer_fromConnection_(self, _o, sb, _c):
            owner = getattr(self, "owner", None)
            if owner is None:
                return
            pb = CoreMedia.CMSampleBufferGetImageBuffer(sb)
            if pb is None:
                return
            Quartz.CVPixelBufferLockBaseAddress(pb, 1)
            try:
                w = Quartz.CVPixelBufferGetWidth(pb)
                h = Quartz.CVPixelBufferGetHeight(pb)
                bpr = Quartz.CVPixelBufferGetBytesPerRow(pb)
                buf = Quartz.CVPixelBufferGetBaseAddress(pb).as_buffer(bpr * h)
                bgra = np.frombuffer(buf, np.uint8).reshape(h, bpr)[:, :w * 4]
                frame = cv2.cvtColor(bgra.reshape(h, w, 4), cv2.COLOR_BGRA2BGR)
            finally:
                Quartz.CVPixelBufferUnlockBaseAddress(pb, 1)
            owner._deliver(frame)

    def make(owner):
        d = HOSXFrameDelegate.alloc().init()
        d.owner = owner
        return d

    _NATIVE_DELEGATE = make
    return make


# Cameras OpenCV has failed to open: straight to AVFoundation next time,
# so a reconnect does not print OpenCV's warning every few seconds.
_NATIVE_ONLY = set()


def open_capture(uid: str, native=True):
    """A capture for the camera with this unique ID: OpenCV by its current
    index (looked up now -- the numbers move as cameras come and go), else
    AVFoundation when `native`. None when neither opens it."""
    idx = camera_index_of(uid)
    if idx is None:
        return None
    if uid not in _NATIVE_ONLY:
        cap = cv2.VideoCapture(idx)
        if cap is not None and cap.isOpened():
            return cap
        if cap is not None:
            cap.release()
        _NATIVE_ONLY.add(uid)
    if not native:
        return None
    cap = NativeCapture(uid)
    return cap if cap.isOpened() else None


def first_frame(cap, timeout):
    """Read until a frame comes (a camera can take seconds to wake: Iriun
    ~2.2 s) -> the frame, or None by `timeout`."""
    end = time.monotonic() + timeout
    while True:
        ok, frame = cap.read()
        if ok and frame is not None:
            return frame
        if time.monotonic() >= end:
            return None
        time.sleep(0.05)


MAIN_CAMERA_ID = ""          # the main view camera's unique ID, once open


# The supporting view camera (user, 2026-10-18): a second camera beside the
# main (top-down) view camera, looking at the gripper from the side. ERR on
# the Go judges each pickup from it, ERR takes it in, and naming sees the
# objects from the side too. Chosen in Settings by its unique ID; "" = none.
SUPPORT_CAMERA_ID = ""
# The coordinate grid (lines, letters, numbers) on the MAIN view camera's
# picture: off by default (user, 2026-10-18), on in Settings. It is still
# drawn while the board's corners are being set.
SHOW_MAIN_GRID = False
SUPPORT_MAX_SIDE = 1024      # the side view sent to a model, longest side px


class SupportCamera:
    """The supporting view camera on its own grabber thread. Held by its
    unique ID, so a camera plugged in elsewhere (which moves OpenCV's
    numbers) never makes it reopen the wrong one."""

    def __init__(self):
        self._lock = threading.Lock()
        self.uid = None
        self._cap = None
        self._frame = None
        self._at = 0.0
        self._stop = None
        self._thread = None
        self.opened_at = 0.0

    @property
    def index(self):
        """Its OpenCV index now, or None when closed or unplugged."""
        return camera_index_of(self.uid) if self.uid else None

    def open(self, uid):
        """Open the camera with this unique ID (None closes it). -> whether
        it is live."""
        self.close()
        if not uid:
            return False
        stop = threading.Event()
        self._stop, self.uid = stop, uid
        self.opened_at = time.monotonic()
        self._thread = threading.Thread(target=self._loop, args=(uid, stop),
                                        daemon=True)
        self._thread.start()
        return True

    def _loop(self, uid, stop):
        cap = open_capture(uid)
        with self._lock:
            self._cap = cap
        misses = 0
        while not stop.is_set():
            ok, frame = cap.read() if cap is not None else (False, None)
            if stop.is_set():
                break
            if ok and frame is not None:
                with self._lock:
                    self._frame, self._at = frame, time.monotonic()
                misses = 0
            else:
                misses += 1
                if misses % 150 == 0:             # gone a while: reopen it
                    if cap is not None:
                        cap.release()
                    cap = open_capture(uid)
                    with self._lock:
                        self._cap = cap
            time.sleep(0.03)
        if cap is not None:
            cap.release()

    def close(self):
        if self._stop is not None:
            self._stop.set()
        if self._thread is not None:
            self._thread.join(timeout=2.0)
        self._stop = self._thread = None
        with self._lock:
            self._cap, self._frame, self.uid = None, None, None

    def frame(self, max_age=2.0):
        """The newest side-view frame (not to be drawn on), or None when
        there is no supporting camera or it has gone quiet."""
        with self._lock:
            if self._frame is None or time.monotonic() - self._at > max_age:
                return None
            return self._frame


SUPPORT_CAM = SupportCamera()


def support_frame():
    """The supporting view camera's newest frame, or None."""
    return SUPPORT_CAM.frame() if SUPPORT_CAMERA_ID else None


def apply_support_camera():
    """Open the camera SUPPORT_CAMERA_ID names (never the main one); close
    it while that camera is unplugged."""
    uid = SUPPORT_CAMERA_ID
    if not uid or uid == MAIN_CAMERA_ID or camera_index_of(uid) is None:
        uid = None
    if uid == SUPPORT_CAM.uid and (uid is None or SUPPORT_CAM._thread):
        return uid is not None
    if uid is None:
        SUPPORT_CAM.close()
        return False
    idx = camera_index_of(uid)
    print(f"[camera] supporting view camera: {camera_name(idx)} (index {idx})")
    return SUPPORT_CAM.open(uid)


def support_name() -> str:
    """The supporting view camera's name, or "Off"."""
    idx = camera_index_of(SUPPORT_CAMERA_ID) if SUPPORT_CAMERA_ID else None
    return camera_name(idx) if idx is not None else "Off"


def support_status() -> str:
    """For Settings: the supporting view camera's name and whether its
    picture is coming in."""
    if not SUPPORT_CAMERA_ID:
        return "Off"
    idx = camera_index_of(SUPPORT_CAMERA_ID)
    if idx is None:
        return "Not connected"
    if SUPPORT_CAMERA_ID == MAIN_CAMERA_ID:
        return f"{camera_name(idx)} (the main view)"
    if support_frame() is not None:
        return camera_name(idx)
    if SUPPORT_CAM.index == idx and time.monotonic() - SUPPORT_CAM.opened_at < 5.0:
        return f"{camera_name(idx)} - starting..."
    return f"{camera_name(idx)} - no picture"


def support_image_part(max_side=SUPPORT_MAX_SIDE):
    """The side view as a model's image part, or None."""
    f = support_frame()
    if f is None:
        return None
    h, w = f.shape[:2]
    k = min(1.0, max_side / float(max(h, w)))
    if k < 1.0:
        f = cv2.resize(f, (int(w * k), int(h * k)), interpolation=cv2.INTER_AREA)
    ok, jpg = cv2.imencode(".jpg", f, [cv2.IMWRITE_JPEG_QUALITY, 88])
    if not ok:
        return None
    return {"type": "image_url", "image_url": {
        "url": "data:image/jpeg;base64," + base64.b64encode(jpg.tobytes()).decode(),
        "detail": "high"}}


_SUPPORT_VIEW_CACHE = {"key": None, "pic": None}


def shrink_for_display(img, size):
    """`img` shrunk to `size` = (w, h) for drawing, looking the same as one
    INTER_AREA resize. OpenCV's area resize is fast only for exact halvings:
    a 1080p camera picture shrunk to the side-view preview in one step took
    ~20 ms, on the UI thread, for every new side-camera frame (measured
    2026-10-19, 39% of the main thread). Halving by area while the picture
    stays at least `size`, then one bilinear step under 2x, takes ~0.3 ms."""
    w, h = max(1, int(size[0])), max(1, int(size[1]))
    while img.shape[1] >= 2 * w and img.shape[0] >= 2 * h:
        img = cv2.resize(img, (img.shape[1] // 2, img.shape[0] // 2),
                         interpolation=cv2.INTER_AREA)
    if (img.shape[1], img.shape[0]) == (w, h):
        return img
    return cv2.resize(img, (w, h), interpolation=cv2.INTER_LINEAR)


def draw_support_view(canvas, area, video):
    """The supporting view camera's picture, small and live, with its name:
    in `area` (a margin of the camera view beside the board) when it is wide
    enough, else in the view's bottom-left corner -- over the band the
    gripper cannot reach."""
    f = support_frame()
    if f is None:
        return None
    x0, y0, x1, y1 = (int(v) for v in area)
    if x1 - x0 < 120:
        vx0, vy0, vx1, vy1 = (int(v) for v in video)
        bw = max(160, (vx1 - vx0) // 4)
        x0, x1 = vx0 + 8, vx0 + 8 + bw
        y1 = vy1 - 8
        y0 = y1 - int(bw * f.shape[0] / f.shape[1]) - 24
    bw = x1 - x0
    bh = int(bw * f.shape[0] / float(f.shape[1]))
    bh = min(bh, max(40, y1 - y0 - 24))
    bw = int(bh * f.shape[1] / float(f.shape[0]))
    if bw < 40 or bh < 30:
        return None
    key = (id(f), bw, bh)
    if _SUPPORT_VIEW_CACHE["key"] != key:
        _SUPPORT_VIEW_CACHE["key"] = key
        _SUPPORT_VIEW_CACHE["pic"] = shrink_for_display(f, (bw, bh))
    pic = _SUPPORT_VIEW_CACHE["pic"]
    H, W = canvas.shape[:2]
    if y0 < 0 or x0 < 0 or y0 + 24 + bh > H or x0 + bw > W:
        return None
    cv2.rectangle(canvas, (x0 - 1, y0 - 1), (x0 + bw, y0 + 24 + bh), (0, 0, 0), 1)
    cv2.rectangle(canvas, (x0, y0), (x0 + bw - 1, y0 + 23), C_CARD, -1)
    label, font = f"Supporting view: {support_name()}", cv2.FONT_HERSHEY_SIMPLEX
    if cv2.getTextSize(label, font, 0.42, 1)[0][0] > bw - 12:
        while len(label) > 4 and cv2.getTextSize(label + "...", font, 0.42,
                                                 1)[0][0] > bw - 12:
            label = label[:-1]
        label = label.rstrip() + "..."
    cv2.putText(canvas, label, (x0 + 6, y0 + 16), font, 0.42, C_TEXT, 1,
                cv2.LINE_AA)
    canvas[y0 + 24:y0 + 24 + bh, x0:x0 + bw] = pic
    return (x0, y0, x0 + bw, y0 + 24 + bh)


def draw_support_popup(canvas, video, mouse):
    """The supporting view camera in a pop-up over the main view, opened by
    the Side view button beside the camera list (user, 2026-10-18), with
    "Save empty gripper" (ERR-go's reference photo, 2026-10-22). Returns
    (card rect, close-button rect, save-button rect or None)."""
    vx0, vy0, vx1, vy1 = (int(v) for v in video)
    f = support_frame()
    cw = max(320, int((vx1 - vx0) * 0.62))
    cw = min(cw, vx1 - vx0 - 16)
    if f is not None:
        ph = int((cw - 24) * f.shape[0] / float(f.shape[1]))
        ph = min(ph, vy1 - vy0 - 16 - 64)
        pw = int(ph * f.shape[1] / float(f.shape[0]))
        cw = max(320, pw + 24)
    else:
        pw, ph = cw - 24, 120
    ch = 52 + ph + 12
    x0 = vx0 + (vx1 - vx0 - cw) // 2
    y0 = vy0 + (vy1 - vy0 - ch) // 2
    card = (x0, y0, x0 + cw, y0 + ch)
    css_rect(canvas, card, 14, C_CARD, (0, 0, 0))
    title = "Supporting view"
    name = support_name() if SUPPORT_CAMERA_ID else ""
    draw_text(canvas, title, (x0 + 16, y0 + 32), 0.56, C_TEXT, 1, weight=600)
    if name:
        tw = text_size(title, 0.56, 1, weight=600)[0]
        draw_text(canvas, name, (x0 + 26 + tw, y0 + 32), 0.5, C_TEXT_FAINT, 1)
    close = Button("X", x0 + cw - 46, y0 + 10, x0 + cw - 14, y0 + 42, "close",
                   style="text")
    close.draw(canvas, hover=close.contains(*mouse), shadow=False)
    save = None
    if f is not None:
        label = ("Save empty gripper again" if grip_empty_reference() is not None
                 else "Save empty gripper")
        sw = round(button_width(label, outlined=True, scale=0.5))
        save = Button(label, close.x0 - 10 - sw, y0 + 10, close.x0 - 10, y0 + 42,
                      "save_empty", scale=0.5)
        save.draw(canvas, hover=save.contains(*mouse), shadow=False)
    px, py = x0 + 12, y0 + 52
    if f is not None and pw > 0 and ph > 0:
        canvas[py:py + ph, px:px + pw] = shrink_for_display(f, (pw, ph))
        cv2.rectangle(canvas, (px - 1, py - 1), (px + pw, py + ph), (0, 0, 0), 1)
    else:
        msg = ("No supporting view camera is chosen - pick one in Settings > Cameras."
               if not SUPPORT_CAMERA_ID else f"Supporting view: {support_status()}")
        draw_text(canvas, msg, (px + 4, py + ph // 2), 0.5, C_TEXT_DIM, 1)
    return (card, (close.x0, close.y0, close.x1, close.y1),
            None if save is None else (save.x0, save.y0, save.x1, save.y1))


def save_empty_gripper() -> str:
    """The supporting view now, saved as ERR-go's empty-gripper reference
    (GRIP_EMPTY_REF_PATH). -> what to tell the operator."""
    f = support_frame()
    if f is None:
        return "No supporting view picture to save."
    if not cv2.imwrite(GRIP_EMPTY_REF_PATH, f):
        return "Could not save the empty-gripper photo."
    print(f"[err] {ERR_NAME}: empty-gripper reference saved to {GRIP_EMPTY_REF_PATH}")
    return ("Saved the empty gripper: ERR-go compares each pickup with it. "
            "Save it again whenever the side camera is moved.")


class CameraManager:
    """Opens the main view camera and keeps its newest frame ready.

    Every camera macOS reports is offered (user, 2026-11-02: "not detecting
    all the cameras"): the old list held only the ones that sent a frame
    within half a second at startup, which dropped Iriun (~2.2 s to wake)
    and any camera OpenCV cannot open (those go through AVFoundation, see
    NativeCapture). Cameras are held by unique ID -- OpenCV numbers them by
    ID, sorted, so plugging one in can move every number. The list is
    re-read every RESCAN_EVERY on its own thread; nothing that is open is
    touched by a rescan.
    """

    RECONNECT_EVERY = 3.0
    RESCAN_EVERY = 3.0
    QUICK_FRAME_S = 0.6      # startup: a camera that is up at once
    FIRST_FRAME_S = 4.0      # a chosen camera may take seconds to wake

    def __init__(self, settings: Optional[CameraSettings] = None):
        self.settings = settings or CameraSettings()
        self._init_frame_state()
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._rescan_now = threading.Event()
        self.cap = None
        self.uid = ""
        self.switching = None        # the unique ID being opened, if any
        self._switches = []          # (ok, uid) for the UI thread to report
        self._last_ok = time.time()
        self._next_reconnect = 0.0
        devs = camera_devices(refresh=True)
        if not devs:
            raise RuntimeError("No cameras found.")
        if not self._open_first([u for _, u in devs]):
            raise RuntimeError("No camera sent a picture.")
        self._thread = threading.Thread(target=self._grab_loop, daemon=True)
        self._thread.start()
        self._scanner = threading.Thread(target=self._rescan_loop, daemon=True)
        self._scanner.start()

    def _init_frame_state(self):
        self._latest = None
        self._seq = 0
        self._newest = (None, 0)

    def _publish(self, frame):
        """Make `frame` the newest one. Each grab is a new array that nothing
        ever draws on, so readers may keep a reference without copying. The
        (frame, number) pair is replaced in one assignment so a reader can
        never pair one frame with another's number."""
        if frame is not None:
            self._seq += 1
        self._latest = frame
        self._newest = (frame, self._seq)

    def _open_first(self, uids):
        """Startup: the saved main view camera first (given time to wake),
        then the others in OpenCV's order -- first through OpenCV with a
        short wait, then any of them with the long wait and AVFoundation.

        isOpened() alone is not proof of a working camera: on macOS, an
        index cv2 has opened but has no camera permission for (or that
        another app already has open) still reports isOpened() == True,
        and every read() from it then fails forever. Only a real frame
        counts; a printed reason is the only way "camera 0 shows nothing"
        is distinguishable from "camera 0 was never offered" from the
        console.
        """
        saved = MAIN_CAMERA_ID if MAIN_CAMERA_ID in uids else None
        others = [u for u in uids if u != saved]
        tries = ([(saved, self.FIRST_FRAME_S, True)] if saved else [])
        tries += [(u, self.QUICK_FRAME_S, False) for u in others]
        tries += [(u, self.FIRST_FRAME_S, True) for u in others]
        for uid, wait, native in tries:
            cap = open_capture(uid, native=native)
            if cap is None:
                continue
            frame = first_frame(cap, wait)
            if frame is not None:
                self._take(uid, cap, frame)
                return True
            cap.release()
            if wait == self.FIRST_FRAME_S:
                print(f"[camera] {camera_name(camera_index_of(uid))} opened but "
                      f"sent no frame -- check System Settings > Privacy & "
                      f"Security > Camera for this app, and that no other app "
                      f"(Zoom, FaceTime, Photo Booth...) already has it open")
        return False

    def _take(self, uid, cap, frame):
        """Make `cap` the main view camera, its first frame shown at once."""
        global MAIN_CAMERA_ID
        with self._lock:
            old, self.cap, self.uid = self.cap, cap, uid
            MAIN_CAMERA_ID = uid
            self._publish(frame)
            self._last_ok = time.time()
        if old is not None:
            old.release()

    def _grab_loop(self):
        """Keep the newest frame ready.

        cap.read() blocks until the sensor has a frame -- a third of the
        budget at 30 fps, spent doing nothing. On its own thread the UI loop
        always finds a frame waiting and never waits on the camera.

        A camera that gets unplugged mid-run just starts returning `False`
        forever -- there's no exception to catch, `_latest` simply stops
        updating and the app would sit there showing the last frame it ever
        grabbed. So a read failure that persists past RECONNECT_EVERY
        triggers a reopen by unique ID (_reconnect), on this thread, at that
        same cadence -- if the camera comes back (replugged, woken up), the
        feed comes back with it instead of staying frozen.

        A camera whose read() returns instantly (no frame ever coming, e.g.
        permission not yet granted, or another app already has the device)
        used to spin this loop close to CPU-bound: read() returning in
        under a millisecond meant only the 20ms sleep stood between one
        iteration and the next, taking the GIL and this manager's OWN LOCK
        with it every single time. That lock is also what a camera switch
        (_take) needs -- so a camera stuck in this state didn't just
        burn CPU, it starved every other thread of the lock badly enough to
        look exactly like a frozen window with no error at all. The sleep
        now always runs (moved out of the `else` branch), so a read that
        returns instantly is throttled the same as one that legitimately
        fails, and the lock is held only for the instant of the read/reopen
        itself rather than being fought over every native VideoCapture call.
        """
        while not self._stop.is_set():
            with self._lock:
                cap = self.cap
                ok, frame = (cap.read() if cap is not None else (False, None))
            if ok:
                self._publish(frame)
                self._last_ok = time.time()
            else:
                now = time.time()
                if now >= self._next_reconnect:
                    self._next_reconnect = now + self.RECONNECT_EVERY
                    self._reconnect()
            time.sleep(0.02)

    def _reconnect(self):
        """Reopen the main view camera by its unique ID -- only while it is
        plugged in, so a camera that moved into its old number is never
        opened in its place. The old capture keeps its place until the new
        one is open."""
        uid = self.uid
        if self.switching is not None or camera_index_of(uid) is None:
            return
        cap = open_capture(uid)
        if cap is None:
            return
        with self._lock:
            if self.uid != uid or self.switching is not None:
                cap.release()
                return
            old, self.cap = self.cap, cap
        if old is not None:
            old.release()

    def _rescan_loop(self):
        while not self._stop.is_set():
            self._rescan_now.wait(self.RESCAN_EVERY)
            self._rescan_now.clear()
            if self._stop.is_set():
                break
            try:
                camera_devices(refresh=True)
            except Exception as e:
                print(f"[camera] rescan failed: {e}")

    def rescan(self):
        """Read the camera list again now (the dropdown's refresh icon).
        -> how many cameras there are. Enumerating opens nothing."""
        return len(camera_devices(refresh=True))

    def select(self, cam) -> bool:
        """Switch the main view to a camera (unique ID, or OpenCV index).
        The new camera opens on its own thread while the old one keeps
        showing; take_switches() reports how it went. -> whether a switch
        started."""
        uid = cam if isinstance(cam, str) else camera_id_at(cam)
        if not uid or uid == self.uid or self.switching is not None:
            return False
        self.switching = uid
        threading.Thread(target=self._switch_to, args=(uid,), daemon=True).start()
        return True

    def _switch_to(self, uid):
        global SUPPORT_CAMERA_ID
        frame = None
        cap = open_capture(uid)
        if cap is not None:
            frame = first_frame(cap, self.FIRST_FRAME_S)
            if frame is None:
                cap.release()
        ok = frame is not None
        if ok:
            if SUPPORT_CAM.uid == uid:
                SUPPORT_CAM.close()          # one camera cannot be both views
                SUPPORT_CAMERA_ID = ""
            self._take(uid, cap, frame)
            print(f"[camera] main view camera: {camera_name(camera_index_of(uid))}")
        else:
            print(f"[camera] {camera_name(camera_index_of(uid))} sent no picture; "
                  f"keeping the current camera")
        self.switching = None
        self._switches.append((ok, uid))

    def take_switches(self):
        """[(ok, uid)] for switches finished since the last call."""
        out, self._switches = self._switches, []
        return out

    def read(self):
        frame = self._latest
        if frame is None:
            return False, None
        out = self.settings.apply(frame)
        return True, out if out is not frame else frame.copy()

    def latest(self):
        """(newest raw frame, its sequence number), without copying or
        adjusting it -- the frame loop does that once per new frame rather
        than once per window redraw. The frame must not be drawn on."""
        return self._newest

    def current_index(self):
        """The main view camera's OpenCV index now (None while unplugged)."""
        return camera_index_of(self.uid)

    def release(self):
        self._stop.set()
        self._rescan_now.set()
        self._thread.join(timeout=2.0)
        if self._thread.is_alive():
            print("[camera] grabber did not stop; leaving the device to exit")
            return
        with self._lock:
            if self.cap is not None:
                self.cap.release()
                self.cap = None


class HeadTracker:
    """Where the gripper's head is, from what is sent and what the board says
    (user, 2026-10-14: "it must not move with the gripper down"). Down time
    builds up while hd, hx or p3 runs and is given back while hu runs (at
    the pickup's own hu scale); a stop -- ours or the board's -- ends the
    run. The head is up when nothing runs and no down time is left. No
    sensor reads the height: this is the same arithmetic the pickup's own
    lift uses (hu for as long as the descent took).

    "Up" is the height the app carries things at: a pickup's lift and a
    release's lift ending as planned set it (reset), whatever the hx in
    between did. A descent the board never ended (no contact in 25 s) is
    not 25 s of lift: a safety lift is at most one whole descent the board
    has reported (else a release's lift) plus the pickup's hx."""

    DOWN = ("hd",)
    UP_TOL_S = 0.15              # this much down time left still counts as up
    LIFT_MARGIN_S = 0.5          # a safety lift runs this much longer

    def __init__(self):
        self.down_s = 0.0
        self.moving = None       # "down" / "up" while a height move runs
        self.since = 0.0
        self.down_from = 0.0     # when the move down now running began
        self.longest_s = 0.0     # the longest descent the board itself ended
        self._lock = threading.Lock()

    def _settle(self, now):
        dt = max(0.0, now - self.since)
        if self.moving == "down":
            self.down_s += dt
        elif self.moving == "up":
            self.down_s = max(0.0, self.down_s - dt / max(AUTO_PICKUP_HU_SCALE, 0.05))
        self.since = now

    def note(self, token, now=None):
        """A command going to the board."""
        t = str(token or "").strip().lower()
        if t not in self.DOWN and t not in ("hu", "s"):
            return
        now = time.monotonic() if now is None else now
        with self._lock:
            self._settle(now)
            was = self.moving
            self.moving = ("down" if t in self.DOWN else "up" if t == "hu" else None)
            if self.moving == "down" and was != "down":
                self.down_from = now

    def board_stopped(self, now=None):
        """The board ended a move DOWN by itself (IR sensor, limit switch,
        p3 at its height). A lift only ever ends with our own s."""
        now = time.monotonic() if now is None else now
        with self._lock:
            if self.moving != "down":
                return
            self._settle(now)
            self.longest_s = max(self.longest_s, now - self.down_from)
            self.moving = None

    def down_left(self, now=None) -> float:
        now = time.monotonic() if now is None else now
        with self._lock:
            d, m, since = self.down_s, self.moving, self.since
        dt = max(0.0, now - since)
        if m == "down":
            d += dt
        elif m == "up":
            d = max(0.0, d - dt / max(AUTO_PICKUP_HU_SCALE, 0.05))
        return d

    def is_up(self, now=None) -> bool:
        with self._lock:
            moving = self.moving
        return moving is None and self.down_left(now) <= self.UP_TOL_S

    def lift_time(self, now=None) -> float:
        """How long an hu brings the head fully back up from here."""
        cap = max(self.longest_s, AUTO_RELEASE_DURATION_S)
        return min(self.down_left(now), cap) * AUTO_PICKUP_HU_SCALE + self.LIFT_MARGIN_S

    def reset(self):
        """Up: the app's own lift has finished (or nothing has moved yet)."""
        with self._lock:
            self.down_s, self.moving, self.since = 0.0, None, time.monotonic()


HEAD = HeadTracker()


