def grip_command(angle) -> str:
    """The serial token for a jaw angle, clamped to what the servo accepts."""
    deg = int(round(float(angle)))
    deg = max(GRIP_MIN_DEG, min(GRIP_MAX_DEG, deg))
    return f"{GRIP_CMD_LETTER}{deg}"


