def _teach_settings_of(data):
    """The class settings in a record, cleaned."""
    out = {}
    hints = data.get("hints") if isinstance(data.get("hints"), dict) else {}
    out["hints"] = {str(k).strip()[:40]: str(v or "").strip()[:120]
                    for k, v in list(hints.items())[:40] if str(k).strip() and str(v or "").strip()}
    out["description"] = str(data.get("description") or "").strip()[:200]
    tags = data.get("tags") or ""
    if isinstance(tags, (list, tuple)):
        tags = ", ".join(str(t) for t in tags)
    out["tags"] = str(tags)[:120]
    out["runs"] = str(data.get("runs") or "").strip()[:3]
    out["time_limit"] = str(data.get("time_limit") or "").strip()[:5]
    for key in ("step_mode", "strict", "pinned"):
        out[key] = bool(data.get(key))
    return out
