def _teach_the(name):
    """'plate' -> 'the plate'. A name that already starts with the, a, or an
    is left alone."""
    name = (name or "").strip()
    if not name:
        return ""
    if name.lower().startswith(("the ", "a ", "an ")):
        return name
    return "the " + name


def _teach_sentence(step):
    """One block as a sentence. No cell and no command code. A step marked
    gentle says so: 'Pick up the glass, gently.'"""
    text = _teach_sentence_core(step)
    if step.get("gentle") and text.endswith("."):
        text = text[:-1] + ", gently."
    return text


def _teach_sentence_core(step):
    kind = step.get("kind")
    obj = _teach_the(step.get("object"))
    extra = (step.get("extra") or "").strip()
    if kind == "go_to":
        return f"Go to {obj}." if obj else "Go to an object."
    if kind == "pick_up":
        return f"Pick up {obj}." if obj else "Pick up an object."
    if kind == "place":
        return f"Place {obj}." if obj else "Place what you are holding."
    if kind == "press":
        return f"Press on {obj}." if obj else "Press."
    if kind == "release":
        return "Release."
    if kind == "open":
        return f"Open {obj}." if obj else "Open it."
    if kind == "close":
        return f"Close {obj}." if obj else "Close it."
    if kind == "pour":
        into = f" into {obj}" if obj else ""
        if not extra or extra.lower() in ("all", "1", "1.0", "everything"):
            return f"Pour{into}."
        return f"Pour {extra}{into}."
    if kind == "slice":
        return f"Slice {obj or 'it'}, {extra or '1'} times."
    if kind == "wait":
        secs = extra or "1"
        return f"Wait {secs} second{'' if secs in ('1', '1.0') else 's'}."
    return "Do the next step."


def _teach_alias(action):
    key = re.sub(r"[\s\-]+", " ", str(action or "").strip().lower())
    key = key.replace(" ", "_") if key.replace(" ", "_") in TEACH_KIND else key
    if key in TEACH_KIND:
        return key
    return TEACH_ALIASES.get(key) or TEACH_ALIASES.get(key.replace("_", " "))


def _is_command(step):
    """A single robot step. An Action node is not a command, even though
    both can sit in a step list."""
    return (isinstance(step, dict) and step.get("kind") in TEACH_KIND
            and step.get("node") not in TEACH_NODE)


def _node_kind(step):
    if not isinstance(step, dict):
        return None
    node = str(step.get("node") or "").strip().lower()
    if node in TEACH_NODE:
        return node
    if step.get("kind") in TEACH_KIND:
        return "command"
    return None


def _blank_command(kind):
    return {"kind": kind, "object": "", "extra": ""}


def _blank_node(node):
    if node in ("if", "elif", "ask"):
        return {"node": node, "condition": "", "steps": []}
    if node == "else":
        return {"node": "else", "steps": []}
    if node == "repeat":
        return {"node": "repeat", "times": "2", "condition": "", "max": "", "steps": []}
    if node == "note":
        return {"node": "note", "text": ""}
    if node == "use":
        return {"node": "use", "class": ""}
    return {"node": "action", "steps": []}


def _teach_int(value, default, low=1, high=TEACH_REPEAT_LIMIT):
    try:
        number = int(float(str(value).strip()))
    except (TypeError, ValueError):
        return default
    return max(low, min(high, number))


def _repeat_times(node):
    return _teach_int(node.get("times"), 2)


def _repeat_max(node):
    return _teach_int(node.get("max"), TEACH_REPEAT_MAX)


def _repeat_until(node):
    text = (node.get("condition") or "").strip()
    if text.lower().startswith("until "):
        text = text[6:].strip()
    return text.rstrip(":").strip()


def _teach_question(node):
    q = (node.get("condition") or "").strip() or "Shall I go on?"
    return q if q.endswith("?") else q + "?"


def _teach_chain(steps, i):
    """The If or Ask at `i`, with the Else ifs and the Else right under it,
    and the index after them."""
    chain = [steps[i]]
    j = i + 1
    while j < len(steps) and _node_kind(steps[j]) == "elif":
        chain.append(steps[j])
        j += 1
    if j < len(steps) and _node_kind(steps[j]) == "else":
        chain.append(steps[j])
        j += 1
    return chain, j


def _teach_group(steps, i):
    """A chain when `i` starts one, else the node alone."""
    if _node_kind(steps[i]) in TEACH_HEADS:
        return _teach_chain(steps, i)
    return [steps[i]], i + 1


def _branch_line(node):
    kind = _node_kind(node)
    if kind == "if":
        return _if_line(node.get("condition"))
    if kind == "elif":
        return "Otherwise, i" + _if_line(node.get("condition"))[1:]
    if kind == "ask":
        return f"Ask the operator: {_teach_question(node)} If the answer is yes:"
    return "Otherwise:"


def _teach_seconds(cmd):
    kind = cmd.get("kind")
    extra = (cmd.get("extra") or "").strip()
    try:
        number = float(extra) if extra else 1.0
    except ValueError:
        number = 1.0
    if kind == "wait":
        return max(0.0, number)
    if kind == "slice":
        return TEACH_STEP_SECONDS["slice"] * max(1.0, number)
    return float(TEACH_STEP_SECONDS.get(kind, 8))


def _teach_estimate(steps):
    """Seconds for a step list. An If chain counts as its longest branch,
    since only one branch runs. A Repeat counts each round, and Repeat
    until counts one round, since it may stop after the first."""
    total = 0.0
    steps = list(steps or [])
    i = 0
    while i < len(steps):
        step = steps[i]
        kind = _node_kind(step)
        if kind == "command":
            total += _teach_seconds(step)
        elif kind == "action":
            total += sum(_teach_seconds(s) for s in step.get("steps") or [] if _is_command(s))
        elif kind in ("if", "ask", "elif", "else"):
            chain, j = _teach_group(steps, i)
            total += max(_teach_estimate(node.get("steps")) for node in chain)
            i = j
            continue
        elif kind == "repeat":
            rounds = 1 if _repeat_until(step) else _repeat_times(step)
            total += rounds * _teach_estimate(step.get("steps"))
        i += 1
    return total


def _teach_duration(seconds):
    seconds = int(round(seconds))
    if seconds < 90:
        return f"{seconds} s"
    return f"{int(round(seconds / 60.0))} min"


def _teach_ago(stamp):
    """'5 min ago' for an ISO time, '' when it cannot be read."""
    try:
        then = datetime.datetime.fromisoformat(str(stamp))
    except ValueError:
        return ""
    gone = (datetime.datetime.now() - then).total_seconds()
    if gone < 60:
        return "just now"
    if gone < 3600:
        return f"{int(gone // 60)} min ago"
    if gone < 86400:
        return f"{int(gone // 3600)} h ago"
    return f"{int(gone // 86400)} d ago"


def _teach_clause(step):
    """A command as the middle of a sentence: 'pick up the sponge'."""
    text = _teach_sentence(step).rstrip(".")
    return text[:1].lower() + text[1:]


def _teach_explain_steps(steps):
    parts = []
    steps = list(steps or [])
    i = 0
    while i < len(steps):
        step = steps[i]
        kind = _node_kind(step)
        if kind == "command":
            parts.append(_teach_clause(step))
        elif kind == "action":
            parts.extend(_teach_clause(s) for s in step.get("steps") or [] if _is_command(s))
        elif kind in ("if", "ask", "elif", "else"):
            chain, j = _teach_group(steps, i)
            bits = []
            for node in chain:
                inner = _teach_explain_steps(node.get("steps"))
                body = ", then ".join(inner) if inner else "do nothing"
                nk = _node_kind(node)
                cond = _if_line(node.get("condition"))[3:].rstrip(":")
                if nk == "if":
                    bits.append(f"if {cond}, {body}")
                elif nk == "elif":
                    bits.append(f"otherwise if {cond}, {body}")
                elif nk == "ask":
                    bits.append(f"ask you \u201c{_teach_question(node)}\u201d and if yes, {body}")
                else:
                    bits.append(f"otherwise, {body}")
            parts.append("; ".join(bits))
            i = j
            continue
        elif kind == "repeat":
            inner = _teach_explain_steps(step.get("steps"))
            body = ", then ".join(inner) if inner else "do nothing"
            until = _repeat_until(step)
            if until:
                parts.append(f"repeat until {until} (at most {_repeat_max(step)} times): {body}")
            else:
                parts.append(f"repeat {_repeat_times(step)} times: {body}")
        i += 1
    return parts


def _teach_path_label(steps, path):
    """'Step 3 > Pick up' for a check's location. (The UI font has no ›.)"""
    if path is None:
        return "The class"
    if isinstance(path, int):
        path = (path,)
    steps = list(steps or [])
    if not path or not (0 <= path[0] < len(steps)):
        return "The class"
    node = steps[path[0]]
    bits = [f"Step {path[0] + 1}"]
    kind = _node_kind(node)
    if kind in TEACH_NODE:
        bits.append(TEACH_NODE[kind][1])
    cur = node
    for j in path[1:]:
        kids = cur.get("steps") or []
        if not (0 <= j < len(kids)):
            break
        cur = kids[j]
        ck = _node_kind(cur)
        bits.append(TEACH_KIND[cur["kind"]][1] if ck == "command" else TEACH_NODE[ck][1])
    return " > ".join(bits)


def _if_line(condition):
    cond = (condition or "").strip()
    if not cond:
        cond = "the condition is true"
    if cond.lower().startswith("if "):
        cond = cond[3:].strip()
    if cond.endswith(":"):
        cond = cond[:-1].strip()
    return f"If {cond}:"


def _teach_walk(steps, found):
    """Every command in `steps`, including commands inside Action, If, and Else."""
    for step in steps or []:
        kind = _node_kind(step)
        if kind == "command":
            found.append(step)
        elif kind in TEACH_NODE:
            _teach_walk(step.get("steps"), found)


# How a class reaches the robot (user, 2026-10-27: "my workflow should be
# converted and given to the task planner for it to actually do
# something"). Each step is written the way the planner works: what the
# gripper holds at that point, and the planner's own command in square
# brackets. The planner still finds every object from the camera.
_TEACH_INTO = ("bowl", "cup", "mug", "glass", "box", "basket", "bin", "jar", "pot",
               "pan", "bucket", "container", "drawer", "sink", "tray", "dustpan")
_TEACH_FRACTIONS = {"all": 1.0, "everything": 1.0, "all of it": 1.0, "half": 0.5,
                    "a half": 0.5, "third": 0.33, "a third": 0.33, "quarter": 0.25,
                    "a quarter": 0.25, "a little": 0.1, "a splash": 0.1,
                    "a drizzle": 0.1, "most": 0.75, "most of it": 0.75}


def _teach_same(a, b):
    """'sponge' and 'blue sponge' are the same thing to put back."""
    a, b = (a or "").strip().lower(), (b or "").strip().lower()
    if not a or not b:
        return False
    return a == b or bool(re.search(rf"\b{re.escape(a)}\b", b)
                          or re.search(rf"\b{re.escape(b)}\b", a))


def _teach_into(name):
    low = (name or "").lower()
    return "in" if any(re.search(rf"\b{w}(?:e?s)?\b", low) for w in _TEACH_INTO) else "on"


def _teach_fraction(extra):
    """'half' -> 0.5, '25%' -> 0.25, '0.3' -> 0.3. None for other words."""
    e = (extra or "").strip().lower()
    if not e:
        return 1.0
    if e in _TEACH_FRACTIONS:
        return _TEACH_FRACTIONS[e]
    m = re.fullmatch(r"(\d+(?:\.\d+)?)\s*%", e)
    try:
        value = float(m.group(1)) / 100.0 if m else float(e)
    except ValueError:
        return None
    if 1.0 < value <= 100.0 and not m:
        value /= 100.0
    return value if 0.0 < value <= 1.0 else None


def _teach_number(extra, default):
    try:
        value = float((extra or "").strip())
    except ValueError:
        return default
    return value if value > 0 else default


def _teach_step_text(step, held):
    """One step for the planner. `held` is a one-item list: '' for empty
    claws, an object's name, or None when it is not known (after an If)."""
    kind = step.get("kind")
    obj = (step.get("object") or "").strip()
    the = _teach_the(obj)
    h = held[0]
    the_h = _teach_the(h) if h else ""
    extra = (step.get("extra") or "").strip()
    if kind == "go_to":
        text = f"Go to {the}. [goto_coordinate]" if obj else "Go to the next object. [goto_coordinate]"
    elif kind == "pick_up":
        text = f"Pick up {the}. [pickup, above it]" if obj else "Pick up the object here. [pickup]"
        held[0] = obj or None
    elif kind == "place":
        if not obj:
            text = f"Put {the_h or 'what you are holding'} down here. [keep]"
        elif h and _teach_same(obj, h):
            text = f"Put {the} back down where it was picked up. [keep, above its first cell]"
        else:
            text = (f"Put {the_h or 'what you are holding'} down {_teach_into(obj)} {the}. "
                    f"[keep, above it]")
        held[0] = ""
    elif kind == "press":
        if h:
            text = f"Press {the_h} against {the or 'the surface here'}. [press, above it]"
        else:
            text = f"Press {the}. [press, above it]" if obj else "Press here. [press]"
    elif kind == "release":
        text = "Stop pressing and lift up. [release]"
    elif kind == "open":
        text = f"Open {the}. [open_door, above it]" if obj else "Open it. [open_door]"
    elif kind == "close":
        text = f"Close {the}. [close_door, above it]" if obj else "Close it. [close_door]"
    elif kind == "pour":
        what = the_h or "what you are holding"
        into = f" into {the}" if obj else " into the container here"
        frac = _teach_fraction(extra)
        if frac == 1.0:
            text = f"Pour {what}{into}. [pour, above it]"
        elif frac is not None:
            text = f"Pour {extra} of {what}{into}. [pour({frac:g}), above it]"
        else:
            text = f"Pour {extra} of {what}{into}. [pour(FRACTION) for “{extra}”, above it]"
    elif kind == "slice":
        n = int(_teach_number(extra, 1))
        text = (f"Slice {the or 'it'} {n} time{'s' if n != 1 else ''}. "
                f"[slice({obj or 'it'}, {n}), above it]")
    elif kind == "wait":
        secs = _teach_number(extra, 1)
        text = f"Wait {secs:g} second{'s' if secs != 1 else ''}. [wait_X({secs:g})]"
    else:
        text = "Do the next step."
    if step.get("gentle"):
        text = text.replace(". [", ", slowly and gently. [", 1)
    return text


def _teach_render(steps, numbered, number=1, held=None, planner=False):
    """Ordinary-language lines for a step list, and the next number. At the
    top of a class the lines are numbered: an Action's steps, each branch
    line, and each Repeat, so a class reads like a list of commands. With
    `planner`, each step names the planner's command and what is held."""
    lines = []
    steps = list(steps or [])
    held = [""] if held is None else held

    def say(step):
        return _teach_step_text(step, held) if planner else _teach_sentence(step)

    def put(text):
        nonlocal number
        if numbered:
            lines.append(f"{number}. {text}")
            number += 1
        else:
            lines.append(text)

    def inner(sub, state):
        return _teach_render(sub, False, held=state, planner=planner)[0]

    i = 0
    while i < len(steps):
        step = steps[i]
        kind = _node_kind(step)
        if kind == "command":
            put(say(step))
        elif kind == "action":
            subs = [s for s in step.get("steps") or [] if _is_command(s)]
            label = (step.get("label") or "").strip()
            if not subs:
                put(f"Action{': ' + label if label else ''}, with no steps yet.")
            else:
                if numbered or label:
                    lines.append(f"Action: {label}." if label else "Action.")
                for sub in subs:
                    put(say(sub))
        elif kind in ("if", "ask", "elif", "else"):
            chain, j = _teach_group(steps, i)
            ends = []
            for node in chain:
                state = [held[0]]
                put(_branch_line(node))
                body = inner(node.get("steps"), state)
                lines.extend(f"   {line}" for line in body) if body else lines.append(
                    "   Do nothing yet.")
                ends.append(state[0])
            if _node_kind(chain[-1]) != "else":
                ends.append(held[0])           # no branch may run at all
            held[0] = ends[0] if all(e == ends[0] for e in ends) else None
            i = j
            continue
        elif kind == "repeat":
            until = _repeat_until(step)
            if until:
                state = [held[0]]
                body = inner(step.get("steps"), state) or ["Do nothing yet."]
                put(f"Repeat until {until}, at most {_repeat_max(step)} times:")
                lines.extend(f"   {line}" for line in body)
                held[0] = held[0] if state[0] == held[0] else None
            else:
                rounds = _repeat_times(step)
                once = inner(step.get("steps"), [held[0]]) or ["Do nothing yet."]
                # Written out round by round, so no round can be skipped.
                if rounds * len(once) <= 60:
                    put(f"Repeat {rounds} times:")
                    for r in range(1, rounds + 1):
                        body = inner(step.get("steps"), held) or ["Do nothing yet."]
                        lines.append(f"   Round {r} of {rounds}:")
                        lines.extend(f"      {line}" for line in body)
                else:
                    put(f"Repeat the next steps {rounds} times in a row:")
                    lines.extend(f"   {line}" for line in once)
                    held[0] = None
        i += 1
    return lines, number


def _workflow_body(steps):
    """Ordinary-language lines for a branch. Commands stay as sentences."""
    return _teach_render(steps, False)[0]


def _workflow_lines(steps, held=None):
    """Numbered lines for the top of a class, written for the planner."""
    return _teach_render(steps, True, held=held, planner=True)[0]


