# Plain steps from the clipboard (Phase 4): "1. pick up the sponge" and so
# on, read here with no AI. Each pattern is (regex, kind, object group,
# extra group).
_TEACH_PLAIN = (
    (r"(?:go|move|travel|head)\s+(?:over\s+)?(?:to|above)\s+(.+)", "go_to", 1, None),
    (r"(?:pick\s+up|pickup|grab|take|lift\s+up)\s+(.+)", "pick_up", 1, None),
    (r"(?:put|place|set|keep|drop)\s+(?:it\s+|that\s+)?(?:back\s+)?(?:down\s+)?"
     r"(?:on|onto|in|into|inside|on top of|next to|beside)\s+(.+)", "place", 1, None),
    (r"(?:put|place|set|keep)\s+(.+?)\s+(?:back|down)$", "place", 1, None),
    (r"(?:put|place)\s+(?:it\s+)?down$", "place", None, None),
    (r"(?:press|push)\s+(?:down\s+)?(?:on\s+)?(.+)", "press", 1, None),
    (r"(?:release|let\s+go|stop\s+pressing|lift\s+up|lift)$", "release", None, None),
    (r"open\s+(.+)", "open", 1, None),
    (r"(?:close|shut)\s+(.+)", "close", 1, None),
    (r"pour\s+(?:(half|all|a\s+little|a\s+third|a\s+quarter|most|\d+(?:\.\d+)?%?)\s+)?"
     r"(?:of\s+.+?\s+)?(?:in|into)\s+(.+)", "pour", 2, 1),
    (r"(?:slice|cut|chop)\s+(.+?)(?:\s*,?\s*(\d+)\s+times?)?$", "slice", 1, 2),
    (r"wait\s+(?:for\s+)?(\d+(?:\.\d+)?)\s*(?:s|sec|secs|seconds?)?$", "wait", None, 1),
)


def teach_parse_plain(text):
    """Commands from plain numbered or bulleted lines, and the lines that
    were not understood."""
    steps, skipped = [], []
    parts = re.split(r"(?:\n+|(?<=[.;])\s+|\s+(?=\d+[.)]\s))", text or "")
    for raw in parts:
        line = re.sub(r"^\s*(?:\d+[.)]|[-*•])\s*", "", raw or "").strip().rstrip(".;").strip()
        line = re.sub(r"\s+", " ", line)
        if not line:
            continue
        low = line.lower()
        for pattern, kind, obj_at, extra_at in _TEACH_PLAIN:
            m = re.fullmatch(pattern, low)
            if not m:
                continue
            obj = (m.group(obj_at) or "").strip() if obj_at else ""
            obj = re.sub(r"^(?:the|a|an)\s+", "", obj)
            extra = (m.group(extra_at) or "").strip() if extra_at else ""
            steps.append({"kind": kind, "object": obj[:40], "extra": extra[:40]})
            break
        else:
            skipped.append(line)
    return steps, skipped


def class_from_plan(plan, objects, name="From the last run"):
    """A class from a plan that ran: each command becomes its step, with the
    object at each cell named from the board. A put-down on an empty cell
    gets a Note, since a class names objects, never cells."""
    def cell_of(cmd):
        m = re.match(r"goto_coordinate\s*=\s*([A-Za-z]+)\s*,\s*(\d+)", cmd)
        return f"{m.group(1).upper()}{m.group(2)}" if m else None

    def object_at(cell):
        if not cell:
            return ""
        for o in objects or ():
            if str(o.get("center") or "").upper() == cell:
                return str(o.get("name") or "")
        for o in objects or ():
            try:
                if cell in [c.upper() for c in _touch_cells(o)]:
                    return str(o.get("name") or "")
            except Exception:
                continue
        return ""

    actions, current, here, notes = [], [], None, []
    for cmd in parse_plan_commands(plan or ""):
        low = cmd.strip().lower()
        if low.startswith("goto_coordinate"):
            here = cell_of(cmd.strip())
            name_here = object_at(here)
            if name_here:
                current.append({"action": "go to", "object": name_here})
            continue
        what = object_at(here)
        if low == "pickup":
            current.append({"action": "pick up", "object": what})
        elif low == "keep":
            if not what and here:
                notes.append(here)
            current.append({"action": "place", "object": what})
            actions.append(current)
            current = []
        elif low in ("press", "release"):
            current.append({"action": low, "object": what} if low == "press" else {"action": "release"})
        elif low in ("open_door", "close_door"):
            current.append({"action": low.split("_")[0], "object": what})
        elif low.startswith("pour"):
            m = re.search(r"\(([\d.]+)\)", low)
            current.append({"action": "pour", "object": what, "amount": m.group(1) if m else ""})
        elif low.startswith("slice"):
            m = re.search(r"slice\(\s*([^,]+?)\s*,\s*(\d+)\s*\)", cmd, re.I)
            current.append({"action": "slice", "object": (m.group(1) if m else what),
                            "count": m.group(2) if m else "1"})
        elif low.startswith("wait_x"):
            m = re.search(r"\(([\d.]+)\)", low)
            current.append({"action": "wait", "seconds": m.group(1) if m else "1"})
    if current:
        actions.append(current)
    steps = [{"node": "action", "steps": a} for a in actions if a]
    if notes:
        steps.insert(0, {"node": "note", "text": "The run put something down on an empty spot ("
                         + ", ".join(notes) + "). Choose an object there for each Place "
                         "with no object."})
    return {"name": name, "steps": steps}


