class InteractiveGuide:
    """The tour. It dims the window, frames the part a stop is about with
    corner brackets, and points at it from a card with Back, Next, and End
    tour. While it runs, it takes every click and key but Cmd+Q."""

    def __init__(self, teach):
        self.teach = teach
        self.active = False
        self.index = 0
        self.opened_studio = False
        self.rects = {}
        self.steps = TOUR_STEPS
        self._hits = []
        self.part = 1
        self.app = {}           # main sets: task(), set_task(text), planning()
        self._done_at = None
        self._start_name = ""
        self._card = None

    @property
    def practice(self):
        """Part 2: the operator does each step, so clicks and keys go through."""
        return self.active and self.part == 2

    def start(self, at=None, part=1):
        self.active = True
        self.index = 0
        self.part = 2 if part == 2 else 1
        self.steps = PRACTICE_STEPS if self.part == 2 else TOUR_STEPS
        self._done_at = None
        if at == "studio":
            self.index = next(i for i, s in enumerate(self.steps) if s[0] == "studio")
        self._enter()
        if self.part == 2:
            t = self.teach
            if not t.is_dirty():
                t.new_class()
            self._start_name = t.draft.get("name", "")
            return "Interactive guide, part 2: do each step; the guide goes on by itself."
        return "Interactive guide: press Next, or the right arrow, to go on."

    def end(self):
        self.active = False
        if self.opened_studio and self.teach.open:
            self.teach.hide()
        self.opened_studio = False
        return "Interactive guide closed."

    def go(self, delta):
        if not self.active:
            return None
        self._done_at = None
        target = self.index + delta
        if target >= len(self.steps):
            return self.end()
        self.index = max(0, target)
        self._enter()
        return None

    def _enter(self):
        screen = self.steps[self.index][0]
        t = self.teach
        if screen == "studio" and not t.open:
            t.show()
            t.guide = False
            t.guide_offer_until = 0.0
            t.view = None
            self.opened_studio = True
        if screen == "studio":
            t.menu = None
            t.confirm = None
            if t.draft["mode"] not in ("sketch", "flowchart"):
                t.set_mode("sketch")
        if screen == "main" and t.open and self.opened_studio:
            t.hide()
            self.opened_studio = False

    def done(self):
        """Whether the operator has done Part 2's current step."""
        if not self.practice:
            return False
        want = self.steps[self.index][4]
        t = self.teach
        steps = t.draft["steps"]
        commands = t._all_commands(steps)
        kinds = [c.get("kind") for c in commands]
        if want == "named":
            name = t.draft.get("name", "").strip()
            return bool(name) and name != self._start_name.strip()
        if want == "vars":
            return len(t.draft.get("variables") or []) >= 2
        if want == "action":
            return any(_node_kind(s) == "action" for s in steps)
        if want == "goto":
            return "go_to" in kinds
        if want == "goto_obj":
            return any(c.get("kind") == "go_to" and c.get("object") for c in commands)
        if want == "pickup":
            return any(c.get("kind") == "pick_up" and c.get("object") for c in commands)
        if want == "place":
            return "pick_up" in kinds and "place" in kinds[kinds.index("pick_up"):]
        if want == "checked":
            return t.view == "check"
        if want == "saved":
            return (any(c.get("id") == t.draft.get("id") for c in t.classes)
                    and not t.is_dirty())
        if want == "typed":
            return bool(str(self.app.get("task", lambda: "")() or "").strip())
        if want == "planning":
            return bool(self.app.get("planning", lambda: False)())
        return False

    def source_rect(self):
        """The palette tile a "drag this here" arrow starts from."""
        src_key = self.steps[self.index][5] if self.practice else None
        want = _PRACTICE_SOURCES.get(src_key)
        if want is None or not self.teach.open:
            return None
        got = [r for r, a in self.teach._hits if a == want]
        return got[0] if got else None

    def card_contains(self, x, y):
        c = self._card
        return c is not None and c[0] <= x <= c[2] and c[1] <= y <= c[3]

    def target_rect(self, img):
        _screen, key, _title, _text = self.steps[self.index][:4]
        if key is None:
            return None
        t = self.teach
        if key in ("s:center", "s:inspector"):
            return t._zones.get(key[2:])
        if key == "s:status":
            h, w = img.shape[:2]
            return (0, h - 28, w, h)
        if key in _TOUR_STUDIO:
            want = _TOUR_STUDIO[key]
            got = [r for r, a in t._hits if want(a)]
            if not got:
                return None
            return (min(r[0] for r in got), min(r[1] for r in got),
                    max(r[2] for r in got), max(r[3] for r in got))
        r = self.rects.get(key)
        if r is None and key == "quickrun" and self.rects.get("prompt") is not None:
            # Nothing pinned yet: point at where the row of buttons appears.
            p = self.rects["prompt"]
            r = (p[0], p[1] - 46, p[2], p[1] - 6)
        return tuple(int(v) for v in r) if r is not None else None

    def draw(self, img, mouse=(-1, -1)):
        if not self.active:
            return
        self._hits = []
        h, w = img.shape[:2]
        rect = self.target_rect(img)
        if self.practice:
            return self._draw_practice(img, rect, mouse)
        bright = img.copy() if rect is not None else None
        cv2.convertScaleAbs(img, dst=img, alpha=0.32)
        if rect is not None:
            pad, ring = 6, 3
            x0, y0 = max(0, int(rect[0]) - pad), max(0, int(rect[1]) - pad)
            x1, y1 = min(w, int(rect[2]) + pad), min(h, int(rect[3]) + pad)
            # The part shows through a rounded window with a blue ring.
            r = min(16.0, (x1 - x0) / 2.0, (y1 - y0) / 2.0)
            ox0, oy0 = max(0, x0 - ring), max(0, y0 - ring)
            ox1, oy1 = min(w, x1 + ring), min(h, y1 + ring)
            inner = self._coverage(ox1 - ox0, oy1 - oy0,
                                   (x0 - ox0, y0 - oy0, x1 - ox0, y1 - oy0), r)
            outer = self._coverage(ox1 - ox0, oy1 - oy0,
                                   (x0 - ox0 - ring, y0 - oy0 - ring,
                                    x1 - ox0 + ring, y1 - oy0 + ring), r + ring)
            roi = img[oy0:oy1, ox0:ox1].astype(np.float32)
            roi += (bright[oy0:oy1, ox0:ox1].astype(np.float32) - roi) * inner
            roi += (np.asarray(C_BLUE, np.float32) - roi) * np.clip(outer - inner, 0.0, 1.0)
            img[oy0:oy1, ox0:ox1] = (roi + 0.5).astype(np.uint8)
            rect = (x0, y0, x1, y1)
        card = self._card_rect(img, rect)
        if rect is not None:
            self._arrow(img, card, rect)
        self._paint_card(img, card, mouse)

    @staticmethod
    def _coverage(w, h, box, radius):
        """How much of each pixel of a w x h patch a rounded box covers."""
        m = np.zeros((h, w, 3), np.uint8)
        css_rect(m, box, radius, (255, 255, 255))
        return m[:, :, :1].astype(np.float32) / 255.0

    def _draw_practice(self, img, rect, mouse):
        """Part 2: no dimming, so the screen stays usable. A blue ring on the
        part to use, a dashed "drag this here" arrow from the palette, and
        the card. A step done moves on by itself."""
        h, w = img.shape[:2]
        if self.done():
            if self._done_at is None:
                self._done_at = time.monotonic()
            elif time.monotonic() - self._done_at > 0.8:
                self.go(1)
                if not self.active:
                    return
                rect = self.target_rect(img)
        if rect is not None:
            x0, y0 = max(0, int(rect[0]) - 6), max(0, int(rect[1]) - 6)
            x1, y1 = min(w, int(rect[2]) + 6), min(h, int(rect[3]) + 6)
            r = min(16.0, (x1 - x0) / 2.0, (y1 - y0) / 2.0)
            ox0, oy0, ox1, oy1 = max(0, x0 - 3), max(0, y0 - 3), min(w, x1 + 3), min(h, y1 + 3)
            inner = self._coverage(ox1 - ox0, oy1 - oy0, (x0 - ox0, y0 - oy0, x1 - ox0, y1 - oy0), r)
            outer = self._coverage(ox1 - ox0, oy1 - oy0, (x0 - ox0 - 3, y0 - oy0 - 3,
                                                          x1 - ox0 + 3, y1 - oy0 + 3), r + 3)
            roi = img[oy0:oy1, ox0:ox1].astype(np.float32)
            roi += (np.asarray(C_BLUE, np.float32) - roi) * np.clip(outer - inner, 0.0, 1.0)
            img[oy0:oy1, ox0:ox1] = (roi + 0.5).astype(np.uint8)
            rect = (x0, y0, x1, y1)
        source = self.source_rect()
        if source is not None and rect is not None:
            self._drag_arrow(img, source, rect)
        card = self._card_rect(img, rect)
        if rect is not None and rect[2] - rect[0] > w * 0.4:
            # A big target, such as the workflow, stays clear to work in:
            # the card goes to the bottom right corner.
            cw, ch = card[2] - card[0], card[3] - card[1]
            card = (w - cw - 16, h - ch - 44, w - 16, h - 44)
        if rect is not None and source is None:
            self._arrow(img, card, rect)
        self._paint_card(img, card, mouse)
        self._card = card

    @staticmethod
    def _drag_arrow(img, source, target):
        """A dashed curve from the palette tile into the target: drag it here."""
        sx, sy = (source[0] + source[2]) // 2, (source[1] + source[3]) // 2
        tx = (target[0] + target[2]) // 2
        ty = min(target[1] + 170, (target[1] + target[3]) // 2)
        cx, cy = (sx + tx) // 2, max(20, min(sy, ty) - 120)
        pts = [(int((1 - u) ** 2 * sx + 2 * (1 - u) * u * cx + u * u * tx),
                int((1 - u) ** 2 * sy + 2 * (1 - u) * u * cy + u * u * ty))
               for u in np.linspace(0.0, 1.0, 40)]
        for k in range(0, len(pts) - 2, 2):
            cv2.line(img, pts[k], pts[k + 1], C_BLUE, 4, cv2.LINE_AA)
        cv2.arrowedLine(img, pts[-4], pts[-1], C_BLUE, 4, cv2.LINE_AA, tipLength=1.2)
        cv2.circle(img, (sx, sy), 7, C_BLUE, -1, cv2.LINE_AA)
        label = "Drag this here"
        lw, lh = text_size(label, 0.56, 1, weight=650)
        pill = (tx - lw // 2 - 14, ty + 14, tx + lw // 2 + 14, ty + 22 + lh + 14)
        css_rect(img, pill, (pill[3] - pill[1]) / 2.0, C_BLUE)
        draw_text(img, label, (tx - lw // 2, ty + 22 + lh), 0.56, C_BTN_FG, 1, weight=650)

    def _card_rect(self, img, rect):
        h, w = img.shape[:2]
        cw = min(480, w - 32)
        _screen, _key, title, text = self.steps[self.index][:4]
        lines = wrap_text(text, cw - 40, 0.50)
        ch = 92 + round(22 * TEXT_ZOOM) * len(lines) + 58
        if self.practice:
            ch += 40
            if self.steps[self.index][4] == "typed":
                ch += 46 * len(PRACTICE_TASKS)
        if rect is None:
            x0 = (w - cw) // 2
            y0 = max(16, (h - ch) // 2)
            return (x0, y0, x0 + cw, y0 + ch)
        gap = 44
        tx = (rect[0] + rect[2]) // 2
        x0 = max(16, min(w - cw - 16, tx - cw // 2))
        if rect[3] + gap + ch <= h - 16:
            return (x0, rect[3] + gap, x0 + cw, rect[3] + gap + ch)
        if rect[1] - gap - ch >= 16:
            return (x0, rect[1] - gap - ch, x0 + cw, rect[1] - gap)
        y0 = max(16, min(h - ch - 16, (rect[1] + rect[3]) // 2 - ch // 2))
        if rect[2] + gap + cw <= w - 16:
            return (rect[2] + gap, y0, rect[2] + gap + cw, y0 + ch)
        if rect[0] - gap - cw >= 16:
            return (rect[0] - gap - cw, y0, rect[0] - gap, y0 + ch)
        return (x0, max(16, h - ch - 16), x0 + cw, max(16, h - ch - 16) + ch)

    @staticmethod
    def _arrow(img, card, rect):
        """From the card's nearest edge to the frame's nearest edge."""
        cx = min(max((rect[0] + rect[2]) // 2, card[0] + 24), card[2] - 24)
        tx = min(max((card[0] + card[2]) // 2, rect[0] + 10), rect[2] - 10)
        if card[1] >= rect[3]:
            start, end = (cx, card[1]), (tx, rect[3] + 2)
        elif card[3] <= rect[1]:
            start, end = (cx, card[3]), (tx, rect[1] - 2)
        else:
            cy = (card[1] + card[3]) // 2
            ty = min(max(cy, rect[1] + 10), rect[3] - 10)
            if card[0] >= rect[2]:
                start, end = (card[0], cy), (rect[2] + 2, ty)
            else:
                start, end = (card[2], cy), (rect[0] - 2, ty)
        length = max(1.0, math.hypot(end[0] - start[0], end[1] - start[1]))
        tip = min(0.5, 16.0 / length)
        cv2.arrowedLine(img, start, end, C_BG, 7, cv2.LINE_AA, tipLength=tip)
        cv2.arrowedLine(img, start, end, C_BLUE, 3, cv2.LINE_AA, tipLength=tip)

    def _paint_card(self, img, card, mouse):
        x0, y0, x1, y1 = card
        css_rect(img, card, 24, C_CARD, C_BORDER)
        n, total = self.index + 1, len(self.steps)
        head = (f"Part 2: try it  ·  {n} of {total}" if self.practice
                else f"Interactive guide  ·  {n} of {total}")
        draw_text(img, head, (x0 + 20, y0 + 30), 0.46, C_TEXT_FAINT, 1, weight=600)
        bar = (x1 - 136, y0 + 21, x1 - 20, y0 + 27)
        css_rect(img, bar, 3, C_SWITCH_TRACK)
        filled = bar[0] + int((bar[2] - bar[0]) * n / float(total))
        if filled - bar[0] >= 6:
            css_rect(img, (bar[0], bar[1], filled, bar[3]), 3, C_BLUE)
        _screen, _key, title, text = self.steps[self.index][:4]
        draw_text(img, title, (x0 + 20, y0 + 64), 0.66, C_TEXT, 1, weight=650)
        y = y0 + 92
        for line in wrap_text(text, x1 - x0 - 40, 0.50):
            draw_text(img, line, (x0 + 20, y), 0.50, C_TEXT_DIM, 1)
            y += round(22 * TEXT_ZOOM)
        by = y1 - 48
        last = self.index == len(self.steps) - 1
        if self.practice:
            want = self.steps[self.index][4]
            if want == "typed":
                for task in PRACTICE_TASKS:
                    tw = int(round(button_width(task, outlined=True)))
                    b = Button(task, x0 + 20, y, x0 + 20 + min(tw, x1 - x0 - 40), y + 38,
                               "tour", scale=0.52)
                    b.draw(img, hover=b.contains(*mouse))
                    self._hits.append(((b.x0, b.y0, b.x1, b.y1), ("task", task)))
                    y += 46
            if want is not None:
                ok = self._done_at is not None
                draw_text(img, "Done. Going on..." if ok else "Waiting for you to do it...",
                          (x0 + 20, y + 18), 0.50, C_GREEN if ok else C_BLUE, 1, weight=600)
        buttons = [("End tour", ("end",), "ghost")]
        if self.index > 0:
            buttons.append(("Back", ("back",), "ghost"))
        if last and not self.practice:
            # Part 1 ends with Finish, or Part 2, where you do it yourself.
            buttons.append(("Part 2: try it", ("part2",), "ghost"))
        label = "Finish" if last else ("Skip" if self.practice and self.steps[self.index][4]
                                       else "Next")
        buttons.append((label, ("next",), "primary"))
        bx = x1 - 16
        for label, action, style in reversed(buttons):
            bw = int(round(button_width(label, outlined=style != "primary", scale=0.52)))
            b = Button(label, bx - bw, by, bx, by + 34, "tour", style=style, scale=0.52)
            b.draw(img, hover=b.contains(*mouse))
            self._hits.append(((b.x0, b.y0, b.x1, b.y1), action))
            bx -= bw + 8

    def press(self, x, y):
        """A click while the tour runs. Only the card's buttons answer."""
        for (x0, y0, x1, y1), action in self._hits:
            if x0 <= x <= x1 and y0 <= y <= y1:
                if action == ("end",):
                    return self.end()
                if action == ("part2",):
                    return self.start(part=2)
                if action[0] == "task":
                    setter = self.app.get("set_task")
                    if setter is not None:
                        setter(action[1])
                    return f"Task box: {action[1]}"
                return self.go(1 if action == ("next",) else -1)
        return None

    def handle_key(self, key):
        if key in (63235, 65363, 3, 13, 10, 32):
            return self.go(1)
        if key in (63234, 65361, 2):
            return self.go(-1)
        if key == 27:
            return self.end()
        return None


