    def _turn(poly, deg):
        cx, cy = _poly_centroid(poly)
        r = math.radians(deg)
        return [(cx + (x - cx) * math.cos(r) - (y - cy) * math.sin(r),
                 cy + (x - cx) * math.sin(r) + (y - cy) * math.cos(r))
                for x, y in poly]

