    # a plate takes what is pressed onto it on its inner base only, else
    # 2+ cells in from its edge (user, 2026-10-20)
    def _circ(cx, cy, r, n=40):
        return [(cx + r * math.cos(2 * math.pi * k / n),
                 cy + r * math.sin(2 * math.pi * k / n)) for k in range(n)]
    _pl = _po("plate", _circ(10.5, 5.5, 4.3))
